import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch W: the same cases, played out another way.
extension StoryVariants {
    static let variantsW: [CaseTemplate] = [inspectorShoveV1, taxPreparerV1, borrowedTruckV1, contractKillingPlotV1, contractorDepositsV1, flagTheftV1, tireIronAssaultV1, caregiverAccountV1, deerStandTrespassV1, skateparkScuffleV1, junkyardTiresV1, ambushAtHomeV1, vendingMachinePryV1, roommateStabbingV1, shedBreakInV1, rifleAtKidsV1, dumpsterFireV1, parkingKnifeIntentV1, paintCansV1, repeatBarAssaultV1, campusLaptopV1, barGlassInjuryV1, scrapGuttersV1, debtKidnappingV1, tireSlashV1, roadRageBatV1, mailTheftV1, coachShoveRefV1, drunkPorchV1, wrenchAssaultV1, underpassPaintV1, fatalPunchPartyV1, priceTagSwitchV1, poisonCoffeeV1, fenceKickV1, parkingLotAbductionV1, dineDashV1, diveBarShootingV1]

    static let inspectorShoveV1 = SmallCases.make(
        key: "story.inspectorShove",
        category: .violent,
        headlines: ["Building Inspector Knocked Into Lumber Pile at Garage Site", "Neighbor's Phone Video Shows Stop-Work Order Turn Physical"],
        law: "assaultGovOfficial",
        threshold: 6,
        spec: "Assaulted {V}, a county building inspector, while the official was discharging official duties, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a county building inspector, drove to a half-built detached garage on {D}'s lot on {DATE} to post a stop-work notice. {D} came across the yard and shoved {V} into a stack of lumber. A neighbor filmed it from the next driveway. {DL} says {V} walked through a closed gate and was reaching for {D.his} tools.",
        state: [E(.video, 3, "Neighbor's Phone Video", "{D} crosses the yard and pushes {V} into the lumber."), E(.document, 3, "Stop-Work Notice", "A county notice with {V}'s name and the permit number, signed that morning.")],
        defense: [E(.statement, 1, "Closed Gate", "{DL} says the gate was shut and {V} reached for a tool bag.")],
        role: "County building inspector",
        exam: [.direct("What is your job with the county?", "\"I am a building inspector. I review permits, visit job sites, and post notices when work is being done without approval or outside the approved plans.\""), .direct("Why did you go to {D}'s lot on {DATE}?", "\"The garage was half built and the county had no permit on file. I drove out to post a stop-work notice with the permit number and my name.\""), .direct("What happened when you got out of your truck?", "\"I walked to the gate, saw {D} across the yard, and started toward the structure. I was carrying the notice and a stapler to post it.\""), .direct("How did {D} react?", "\"{D} crossed the yard fast, said I could not be there, and shoved me hard with both hands. I fell back into a stack of lumber.\""), .direct("Were you hurt?", "\"I had bruised ribs and a scrape on my forearm from the boards. I called my supervisor, and the sheriff's office took a report.\""), .direct("What did the neighbor's video show?", "\"The whole thing from the next driveway. It shows {D} crossing the yard and pushing me into the lumber. My notice is in my hand as I fall.\""), .cross("The gate was closed when you arrived, wasn't it?", "\"It was latched, not locked. I opened it and walked in. I did not knock because inspectors are allowed on a permitted site.\""), .cross("There was a no-trespassing sign on that gate, wasn't there?", "\"There was a sign near the gate. I saw it. County inspectors may enter when we are posting a stop-work order, though I understand it may look different to an owner.\""), .cross("You did not call out before you walked into the yard, did you?", "\"I did not shout. I walked directly toward the structure. I should have announced myself, and I take that point.\""), .cross("You were reaching toward something on the ground, weren't you?", "\"I was reaching for the stapler in my bag so I could post the notice. I was not reaching for any tool of {D}'s.\""), .cross("{D} did not strike you, only pushed you, correct?", "\"Correct. It was a hard push with both hands. {D} did not hit me with anything and stopped after I fell.\"")],
        theory: ("{D} pushed an inspector who was posting a notice.", "An owner protecting a closed yard and tools."),
        allocution: "\"I lost my temper and I regret it.\"",
        truths: ("{DL} had told a neighbor {D.he} would 'run off' the next inspector.", "A neighbor says the gate had a no-trespassing sign and {V} never called out."),
        defendant: [.direct("Did you push {V}?", "\"Yes. I did. I pushed hard, and I regret that. It happened quickly and I reacted before I thought.\""), .direct("Why did you push {V}?", "\"Someone walked through my gate into my yard without calling out. I thought someone was going after my tools, and I was angry and scared.\""), .direct("Could you see {V}'s county badge or uniform?", "\"Not at first. {V} had a jacket on, and I only saw a person coming toward my structure. I did not see a badge until later.\""), .direct("Did you know you needed a permit for the garage?", "\"I knew I needed one. I had not gotten around to filing the paperwork. I was told I could begin the foundation and sort it out.\""), .direct("What did you do after the push?", "\"I stood there for a second and then helped {V} up. I told {V} I was sorry. I called the sheriff's office myself afterward.\""), .direct("What would you say to {V}?", "\"That I am sorry. I overreacted, and I should have asked who was there and what was needed before I touched anyone.\""), .cross("You told a neighbor you would run off the next inspector, didn't you?", "\"I said something like that after a bad week. I was frustrated with the county, and it was just talk.\""), .cross("A no-trespassing sign hung on your gate, didn't it?", "\"Yes. I put it there to keep out strangers. I did not mean that a county inspector could not come in, but I know how it reads.\""), .cross("You crossed the yard fast and used both hands, didn't you?", "\"Yes. The video shows it. I do not remember deciding to push, and I know how it looks.\""), .cross("You never called out to ask who {V} was, did you?", "\"No. I should have. I did not think, and I went straight at {V}.\""), .cross("You knew you did not have a permit, didn't you?", "\"Yes. I knew. That is why I was on edge when someone showed up at my site.\"")],
        openings: ("A county building inspector came to post a stop-work notice on a half-built garage. {D} crossed the yard and shoved {V} into a stack of lumber, and a neighbor filmed it.", "{D} saw a stranger walk through a closed gate toward {D.his} tools and reacted without thinking. It was a mistake in a moment of fear."),
        closings: ("The video shows {D} crossing the yard and pushing {V} into the lumber. {D} had said {D.he} would run off the next inspector, and {D.he} did.", "A closed gate, a stranger without a word, and a startled owner. The shove was wrong, but it was a reaction and not a plan."),
        timeline: [(-9, "The county flags the garage as unpermitted."), (0, "9 a.m.: {V} arrives with the notice."), (0, "9:06 a.m.: the shove."), (0, "9:40 a.m.: deputies take reports.")],
        identified: "A neighbor's phone video.",
        aggravating: ["The victim was a law enforcement officer performing official duties"],
        mood: .indifferent)

    static let taxPreparerV1 = SmallCases.make(
        key: "story.taxPreparer",
        category: .whiteCollar,
        headlines: ["Storefront Tax Preparer Accused of Opening Phone and Store Accounts in Client's Name", "Retiree's Frozen Credit Leads to Office Records"],
        law: "identityTheft",
        threshold: 9,
        spec: "Knowingly obtained and used the Social Security number and date of birth of {V}, a client, without consent, to open accounts in {V.his} name with the intent to fraudulently represent that {D.he} was {V}.",
        ages: 30...56,
        victim: true,
        summary: "{D} ran a one-room tax office. {V}, 81, a client of eight years, tried to refinance a small loan around {DATE} and was turned down because of four store and phone accounts {V.he} never opened, with $6,300 in unpaid charges. Each application used {V}'s Social Security number and birth date as listed on returns {DL} prepared, and each gave the office's fax line for verification. {DL} says an intern had run copies of every file and that the fax line served the whole office.",
        state: [E(.document, 3, "Account Applications", "Four applications in {V}'s name, each listing the office fax line for verification.", .search), E(.document, 3, "Account Statements", "$6,300 in phone and appliance charges, all unpaid.", .search), E(.digital, 3, "Fax Log", "Verification calls for every account were answered on the office line from a number tied to {D}'s desk.")],
        defense: [E(.document, 1, "Intern Records", "Office time sheets show an intern copied client files during tax season."), E(.document, 1, "Shared Line", "The fax line served four desks.")],
        role: "Fraud analyst",
        exam: [.direct("What did the four accounts have in common?", "\"Each application used {V}'s Social Security number and birth date as they appear on tax returns, and each listed the same office fax line for verification.\""), .direct("How much did the unpaid accounts add up to?", "\"$6,300 in charges across four store and phone accounts. {V} never opened any of them, and found out when a small loan refinance was denied.\""), .direct("Who answered when the lenders called to verify the applications?", "\"Someone on the office line every time. The log traces those calls to a number tied to {D}'s desk, answered by a person who confirmed the details.\""), .direct("What is the relationship between {V} and {D}?", "\"{V} is 81 and has been a client for eight years. {D} prepared {V}'s returns each spring, so {D} had {V}'s numbers on file.\""), .direct("What did you learn about the purchases on the accounts?", "\"A phone bought on one account was sold at a shop {D} visits weekly. An appliance store's camera showed a younger buyer with a backpack on another.\""), .direct("What did {D} tell you about the intern?", "\"That an intern had scanned and copied client files during tax season. {D} said the fax line served four desks and anyone could use it.\""), .cross("The fax line served four desks, didn't it?", "\"Yes. It rang at several desks. That is why I cannot say that the person who answered was {D} and not someone else.\""), .cross("No name was given on the verification calls, was it?", "\"Only the business name. The callers did not hear a personal name, and I cannot confirm a voice.\""), .cross("The intern had access to every client file, didn't the intern?", "\"Yes. The time sheets show the intern copied files during tax season. That is a real possibility we looked into.\""), .cross("The appliance store video does not show {D}, does it?", "\"It shows a younger person with a backpack. It does not show anyone who resembles {D}.\""), .cross("You cannot say who opened the accounts, can you?", "\"I can say how they were opened and which line was used. I cannot say who typed the applications.\"")],
        defenseRole: "Office intern",
        defenseExam: [.direct("What was your job at the office?", "\"I was an intern during tax season. I scanned client files, filed paperwork, and answered phones when the others were busy.\""), .direct("Did you handle client files?", "\"Yes. I scanned them for filing. Part of my job was to run copies of every file before it was put away.\""), .direct("Where were the scanned copies kept?", "\"On a shared drive and in a folder on my desk. Anyone who worked in the office could look at them.\""), .direct("Did you ever answer verification calls?", "\"Sometimes. The office line rang at several desks. If one rang and no one else was free, I picked it up.\""), .direct("What did you say when you answered verification calls?", "\"I gave the business name and asked how I could help. I did not take notes on every call, and I do not recall details.\""), .direct("What did you do after tax season ended?", "\"I went back to school. I did not take any client files, and I did not use any numbers from them.\""), .cross("You do not know who opened the accounts, do you?", "\"No. I do not know who opened any of them. I would never do something like that, and I was surprised to hear about it.\""), .cross("You did not hear {D} talk about opening accounts, did you?", "\"No. I never heard anything like that from {D} or from anyone in the office.\""), .cross("You carry a backpack to school, don't you?", "\"Yes. Most students do. I did not buy a phone with anyone's account, and I am happy to show where I was.\""), .cross("You were there only for the tax season, weren't you?", "\"Yes. A few months in the spring. I was not there for the whole time the accounts were opened.\""), .cross("You do not recall who called to verify the accounts, do you?", "\"No. I answered a lot of calls. I cannot remember who called or what accounts they asked about.\"")],
        theory: ("{D} used a client's numbers and the office line to open accounts.", "An intern with copies of every file and a shared phone line."),
        allocution: "\"I've protected my clients' information for years.\"",
        truths: ("A phone bought on one account was sold at a shop that {DL} visits every week.", "Camera video from the appliance store shows a younger buyer with a backpack and no one resembling {DL}."),
        defendant: [.direct("Did you open accounts in {V}'s name?", "\"No. I never opened an account for {V} or anyone else. I prepare tax returns, and I have never used a client's number for myself.\""), .direct("Why was your office line listed on the applications?", "\"It is the office line for everyone who works here. It rings at four desks, and anyone can pick it up.\""), .direct("Who had access to {V}'s numbers besides you?", "\"The intern, who scanned every file for filing during tax season. The files were stored in the office, and our scanner was a shared machine.\""), .direct("Did you ever sell a phone at a shop you visit?", "\"I go to a shop for repairs and to buy accessories. I do not sell phones there, and I do not know about a phone from those accounts.\""), .direct("How long have you known {V}?", "\"Eight years. {V} was one of my first clients. I would never harm {V}, and I feel terrible about what happened.\""), .direct("What did you do when you learned about the accounts?", "\"I told the investigators everything I could. I gave them access to the office records and the time sheets without being asked twice.\""), .cross("You prepared the returns that listed {V}'s numbers, didn't you?", "\"Yes. I did. That is part of the job, and the numbers were on the returns.\""), .cross("You never checked on the intern's work, did you?", "\"No. I trusted the intern and did not look over the scans. I should have taken more care with client files.\""), .cross("The verification calls were answered at your desk, weren't they?", "\"The log says the number was tied to my desk. I was not the one who answered, and I was often out.\""), .cross("You visit the shop where the phone was sold every week, don't you?", "\"Yes. It is near the office. Many people do. I did not sell a phone there.\""), .cross("You are the only one who had both the files and the account line, aren't you?", "\"No. The intern had the scans and the line rang at several desks, and I told the investigators that right away.\"")],
        openings: ("{V}, 81, was denied a refinance because of four accounts {V} never opened. Each used {V}'s numbers from tax returns {D} prepared, and each listed the office fax line for verification.", "The office line rang at four desks and an intern copied every client file. Many hands touched those numbers, and {D} did not open a single account."),
        closings: ("Four accounts, {V}'s numbers from {D}'s returns, and the same office line answered each verification call. The trail runs through {D}'s desk.", "A shared line, an intern with copies of every file, and a buyer on camera who looks nothing like {D}. Many hands were in those files."),
        timeline: [(-150, "The first account is opened."), (-60, "The intern finishes the season and leaves."), (0, "{V} is turned down for the refinance."), (30, "Fraud analyst traces the office line."), (50, "{DL} is charged.")],
        identified: "The office fax line on each application.",
        aggravating: ["The victim was very old"],
        mood: .wantsConviction,
        impact: "I trusted that office with my whole life.")

    static let borrowedTruckV1 = SmallCases.make(
        key: "story.borrowedTruck",
        category: .property,
        headlines: ["Neighbor Kept Borrowed Flatbed After Hauling Job", "Larceny Charge After Lent Truck Is Spotted at Lake"],
        law: "misdLarceny",
        spec: "Stole a flatbed truck valued at $950 belonging to {V}, on {DATE}.",
        ages: 22...58,
        victim: true,
        summary: "{V} lent {D} a flatbed to haul one load of firewood on {DATE}. The truck did not come back for a month. {D} stopped answering and a deputy later saw it parked at a lake cabin. {V} reported it stolen. {DL} says {V} still owed {D.him} for a month of yard work and told {D.him} to hold the truck.",
        state: [E(.statement, 3, "{V}'s Account", "{V} says the loan covered a single load."), E(.digital, 2, "Call Log", "Eleven calls from {V} over three weeks, none returned.")],
        defense: [E(.statement, 1, "Unpaid Work", "{DL} says {V} owed {D.him} $350 for yard work.")],
        role: "Sheriff's deputy",
        exam: [.direct("Where was the flatbed truck found?", "\"Parked at a lake cabin in the next county, about a month after {V} lent it. I saw it while on patrol and ran the plate.\""), .direct("What did {V} tell you about the loan?", "\"That {V} lent {D} the flatbed for one load of firewood. {V} said it was meant to come back the same day or the next.\""), .direct("How many times had {V} tried to reach {D}?", "\"Eleven calls over three weeks, according to {V}'s log, and none were returned. {V} also left messages asking for the truck.\""), .direct("What did {D} say when you made contact?", "\"That {V} owed {D} $350 for yard work and had said to hold the truck. {D} said the owner had told {D.him} to keep it handy.\""), .direct("What happened to the truck after you spoke with {D}?", "\"{D} returned it the next day, after we called. I inspected it, and there was no major damage, but the odometer showed several hundred miles.\""), .direct("What do you know about the message {D} mentions?", "\"{V} sent a text that said 'keep it handy till I settle up.' We read it, and it is part of the dispute over what was agreed.\""), .cross("{V} did owe {D} some money for work, didn't {V}?", "\"{V} says there was a dispute over a smaller amount. {D} says $350. I could not confirm how much was owed, if anything.\""), .cross("The text from {V} does say 'keep it handy,' doesn't it?", "\"Yes, that is what it says. {V} told me it meant for the firewood haul only, and {D} reads it differently.\""), .cross("{D} returned the truck without being forced, didn't {D.he}?", "\"{D} returned it the next day after we called. I did not have to arrest {D} or seize the truck.\""), .cross("There was no damage to the truck, was there?", "\"No major damage. It was dirty and had more miles, but it ran fine. {V} did not report any broken part.\""), .cross("You do not know what {V} and {D} agreed between them, do you?", "\"No. Each tells a different version. I can only say what the messages, the calls, and the truck's location show.\"")],
        theory: ("{D} kept a loaned truck for a month and ignored the owner.", "A worker who held a truck until paid."),
        allocution: "\"I should have asked for my money, not kept the truck.\"",
        truths: ("{DL} told a friend the truck was 'mine now.'", "{V}'s message said 'keep it handy till I settle up.'"),
        defendant: [.direct("How did you come to have {V}'s truck?", "\"{V} handed me the keys so I could haul a load of firewood. I picked it up and got it done the same day.\""), .direct("Why did you keep it for a month?", "\"{V} owed me $350 for yard work, and I told {V} I would hold the truck until I was paid. {V} messaged to keep it handy.\""), .direct("What did {V}'s message mean to you?", "\"That I could hold the truck until {V} settled up. I took it as permission, and I did not think I was doing anything wrong.\""), .direct("Why did you not answer {V}'s calls?", "\"I was angry about the money. I let them ring because I did not want to argue. I should have picked up and explained.\""), .direct("Where did you take the truck?", "\"A few weekends to a friend's lake cabin. I used it to haul gear. I never sold it or tried to hide it.\""), .direct("How did you feel when the deputy called?", "\"Embarrassed. I took the truck back the next day and told the deputy everything. I wanted to put it behind me.\""), .cross("You told a friend the truck was 'mine now,' didn't you?", "\"I said it as a joke. I did not mean it. It came out the wrong way, and I should not have said it.\""), .cross("{V} told you it was for one load, didn't {V}?", "\"Yes. That was the original request. It was later that we argued about the money.\""), .cross("You let eleven calls go unanswered, didn't you?", "\"Yes. I know how it looks. I should have called back and worked it out.\""), .cross("You used the truck at the lake for weekends, didn't you?", "\"Yes. A weekend or two. I should not have, and I know it was wrong.\""), .cross("You kept it a month, though the loan was for one load, didn't you?", "\"Yes. That is what happened. I was angry about the money, and I made a bad choice.\"")],
        openings: ("{V} lent {D} a flatbed to haul one load of firewood. The truck did not come back for a month, and {D} ignored eleven calls from {V} before a deputy found it at a lake cabin.", "{D} was owed $350 for yard work and held the truck until paid, with a message that said to keep it handy. That is a pay dispute, not a theft."),
        closings: ("One load of firewood and a month of silence, eleven calls ignored, and a truck at a lake cabin. A loan ends when the owner says it does.", "{V} owed {D} for work and wrote to keep the truck handy. Someone who returns a truck as soon as asked has not stolen it."),
        timeline: [(0, "Saturday: {V} lends the flatbed."), (12, "Fifth unanswered call."), (30, "{V} reports the truck stolen; it is found at the lake.")],
        identified: "{V}'s report and a deputy's sighting.",
        impact: "I lost a month of hauling jobs.",
        genders: ["D": .male, "V": .male])

    static let contractKillingPlotV1 = SmallCases.make(
        key: "story.contractKillingPlot",
        category: .violent,
        headlines: ["Spouse-Killing Offer Made to Undercover Deputy, Deputies Say", "Hardware Store Lot Meeting Ends in Arrest"],
        law: "attemptedMurder1",
        threshold: 9,
        spec: "Took overt steps to have {V} killed with malice, premeditation, and deliberation by paying another to do it, on {DATE}.",
        ages: 30...62,
        victim: true,
        summary: "A coworker told deputies that {D} had asked about hiring someone to kill {V}, {D.his} spouse, for $6,000. A deputy posing as a fixer met {D} in a hardware store lot on {DATE}. {D} gave over a down payment of $3,000 and a house key. {DL} says {D.he} was testing whether anyone would really do it and never meant to go through.",
        state: [E(.digital, 3, "Recorded Call", "{D}: 'Do it while {V.he} is at work.'"), E(.physical, 3, "Cash and Key", "$3,000 in an envelope and a copy of a house key.", .search), E(.statement, 3, "Coworker", "{D} asked how to find a hired killer.")],
        defense: [E(.statement, 1, "Testing", "{DL} says {D.he} meant only to see who would answer.")],
        role: "Undercover deputy",
        exam: [.direct("How did you first come to meet {D}?", "\"A coworker told deputies that {D} had asked about hiring someone to kill {D.his} spouse. I was assigned to pose as a fixer and arranged a meeting.\""), .direct("Where did the meeting take place?", "\"In a hardware store parking lot on {DATE}. I wore a recorder and sat in a pickup. {D} approached my window and we talked for several minutes.\""), .direct("What did {D} say about {V}?", "\"{D} named the day and the work shift and said to do it while {V} was at work. {D} said it plainly and repeated the details.\""), .direct("What was the price discussed?", "\"$6,000. {D} said that was fine and handed over a down payment of $3,000 in cash in an envelope.\""), .direct("What else did {D} give you?", "\"A house key. {D} said it was a copy and that the garage door code was written inside the envelope.\""), .direct("What did {D} say when you asked if {D} was sure?", "\"{D} said yes. {D} said it twice and said {D.he} wanted it done soon. The recording captures all of it.\""), .cross("{D} never named a weapon, did {D.he}?", "\"Not that day. {D} left the method to me. We did not discuss how it would be done.\""), .cross("No one was hurt, were they?", "\"No. We arrested {D} immediately after the meeting. {V} was not harmed, and I want to be clear about that.\""), .cross("{D} told you to forget it at one point, didn't {D.he}?", "\"Yes. I wrote that in my report. {D} said it twice, and then continued the conversation and handed over the envelope.\""), .cross("{D} was visibly nervous during the meeting, wasn't {D.he}?", "\"Yes. {D}'s hands were shaking. Many people are nervous at a meeting like this, so I would not read much into it.\""), .cross("You approached {D}, not the other way around, didn't you?", "\"Our meeting was arranged by phone. {D} came to the lot and approached the truck, and I did not pressure {D}.\"")],
        defenseRole: "Defendant's brother",
        defenseExam: [.direct("How are you related to {D}?", "\"{D} is my sibling. We grew up together and we talk almost every week. I have known {D} all my life.\""), .direct("What kind of person is {D}?", "\"Kind, but hot-tempered. {D} says things when angry that {D.he} does not mean. I have heard it many times, and it passes.\""), .direct("Did {D} ever talk to you about {V}?", "\"Yes. {D} complained about the marriage often. I never took it seriously as a plan to hurt anyone.\""), .direct("How did {D} talk when drinking?", "\"Big and loud. {D} would exaggerate and make threats that no one believed, and then apologize the next day.\""), .direct("Did {D} ever say anything that made you worry for {V}?", "\"Once. {D} said it was real. I told {D} to stop talking like that, and {D} laughed it off.\""), .direct("What did you do when you learned about the meeting?", "\"I was stunned. I went to see {D} as soon as I could. {D} was in tears and said {D.he} did not mean it.\""), .cross("{D} said once that it was real, didn't {D.he}?", "\"Once, yes. It was while drinking, and I took it as more of the same. I should have taken it more seriously.\""), .cross("{D} complained about {V} often, didn't {D.he}?", "\"Yes. I would say it was about a fair share of the marriage. It sounded like ordinary frustration to me.\""), .cross("You did not warn {V} about what {D} said, did you?", "\"No. I did not. I did not think it was serious, and I regret that.\""), .cross("You cannot say what {D} meant at the hardware store, can you?", "\"No. I was not there. I can only tell you what I knew of {D}'s way of talking.\""), .cross("You love {D} and want to help, don't you?", "\"Yes. I do. I also want what is true, and I am trying to be honest about it.\"")],
        theory: ("{D} paid to have {D.his} spouse killed.", "Big talk that went no further."),
        allocution: "\"I was out of my mind with anger.\"",
        truths: ("{DL} had searched online for how long an estate takes to settle.", "{DL} asked the deputy to 'forget it' twice before the envelope changed hands."),
        defendant: [.direct("Did you give the deputy money and a key?", "\"Yes. I handed over an envelope with cash and a key. I did it, and I will not pretend otherwise.\""), .direct("Why did you do it?", "\"I wanted to see if anyone would actually go through with it. I was angry and I wanted to test it, not to hurt {V}.\""), .direct("What were you thinking when you said it was fine to do it while {V} was at work?", "\"I was repeating what I had said in anger, without weighing any of it. I never meant for it to become real.\""), .direct("Why did you give the deputy a key?", "\"I made a copy and gave it to prove I was serious. I wanted to see how far it would go. I was not thinking clearly.\""), .direct("Did you ever intend for {V} to be harmed?", "\"No. I did not. I was furious and I said terrible things. I was shocked when it turned into a meeting in a parking lot.\""), .direct("What would you say to {V}?", "\"That I am sorry. I was out of my mind with anger, and I am glad nothing happened. I never meant for you to be in danger.\""), .cross("You searched online for how long an estate takes to settle, didn't you?", "\"Yes. I was worried about money and looked up many things. I did not mean it as a plan.\""), .cross("You told the deputy to 'forget it' twice, and then went on, didn't you?", "\"I did. I was torn. I handed it over anyway, and I do not have a good explanation for that.\""), .cross("You handed over $3,000 in cash, didn't you?", "\"Yes. It was a lot of money, and I did it. I cannot explain why.\""), .cross("You did not call anyone to stop it, did you?", "\"No. I called no one. Looking back, that was the moment to stop it.\""), .cross("You named the day and the work shift, didn't you?", "\"Yes. I said them in the recording. I know how it sounds.\"")],
        openings: ("A coworker told deputies that {D} had asked about hiring someone to kill {D.his} spouse. At a hardware store lot, {D} met a deputy posing as a fixer and handed over $3,000 and a house key.", "{D} talked big when angry and wanted to see whether anyone would really do it. A test that never became a plan is not a murder plot."),
        closings: ("A recorded meeting, a named day, $3,000 in cash and a key. {D} paid to have {V} killed, and the recording says so in {D}'s own voice.", "{D} said it twice and told the deputy to forget it. Talk, anger and a test are not action, and no one was hurt."),
        timeline: [(-21, "{DL} asks a coworker about a hired killer."), (-5, "The coworker calls deputies."), (0, "Noon: the hardware store meeting."), (0, "{DL} is arrested in the lot.")],
        identified: "An undercover recording.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I sleep with the lights on.",
        genders: ["D": .male, "V": .female])

    static let contractorDepositsV1 = SmallCases.make(
        key: "story.contractorDeposits",
        category: .whiteCollar,
        headlines: ["Roofer's Storm Season Deposits Bought No Shingles", "Five Households Wait Under Tarps for Crew That Never Came"],
        law: "falsePretenses",
        threshold: 6,
        spec: "Obtained a $12,800 deposit from {V} by falsely representing that roofing materials had been delivered to a supplier yard for {V.his} roof replacement.",
        ages: 35...58,
        victim: true,
        summary: "After a spring hailstorm, {D}, who runs a roofing company, took deposits from five homeowners totaling $52,000 for replacement roofs. None was finished. {V} paid $12,800 on {DATE} after {DL} sent a photo of shingle pallets and wrote that they were staged at a supplier yard with {V}'s name on them. The pallets belonged to another job. {DL} says storm demand and a ruined supplier account swamped the company and {D.he} never meant to cheat anyone.",
        state: [E(.digital, 3, "Photo and Text", "{DL}: 'Your shingles are staged at the yard. Need deposit to book the crew.'"), E(.document, 3, "Supplier Ledger", "The yard shows no order for {V}'s address, and {DL}'s account was on hold for nonpayment."), E(.document, 2, "Bank Records", "{V}'s deposit went to a fuel card, a truck note and a past customer's refund within a week."), E(.document, 1, "Consumer Complaints", "Four other homeowners filed similar complaints.")],
        defense: [E(.document, 2, "Completed Roofs", "{DL}'s company finished nearly sixty roofs in six years with clean reviews."), E(.document, 2, "Supplier Hold", "The supplier froze {DL}'s account after a bank error on a large payment."), E(.document, 1, "Refund Plan", "{DL} signed a repayment plan with {V} before charges.")],
        role: "Consumer protection investigator",
        exam: [.direct("What did your investigation of {D}'s roofing company find?", "\"Five homeowners paid deposits totaling $52,000 after a spring hailstorm. None of the roofs was finished, and no materials had been bought for any of those five jobs.\""), .direct("What did {D} send {V} to secure the $12,800 deposit?", "\"A photo of shingle pallets and a text that read, 'Your shingles are staged at the yard. Need deposit to book the crew.' {V} paid on {DATE}.\""), .direct("What did the supplier tell you about those pallets?", "\"They belonged to another customer's job. The yard had no order for {V}'s address, and no shingles were staged under {V}'s name.\""), .direct("What was the status of {D}'s account with the supplier?", "\"It was on hold for nonpayment when the text was sent. The supplier confirmed the account had been frozen for about two months.\""), .direct("Where did {V}'s deposit go?", "\"Within a week it went to a fuel card, a truck note, and a refund to a past customer. None of it was spent on materials for {V}'s roof.\""), .direct("How many complaints did you receive?", "\"Four others filed similar complaints. Each described a deposit, a promise that materials were ordered, and no work done.\""), .cross("{D}'s company had a good history before this spring, didn't it?", "\"It did. The company finished nearly sixty roofs in six years with clean reviews. That is part of the record.\""), .cross("A bank error on a large payment led to the supplier hold, didn't it?", "\"I understand that is what {D} says. I saw records suggesting a payment problem, but I cannot say it was the bank's fault.\""), .cross("{D} signed a repayment plan with {V} before any charges, didn't {D.he}?", "\"Yes. A plan was signed. I treat that as a point in {D}'s favor, though it came after the deposit was spent.\""), .cross("Paying old bills with new deposits is not always fraud, is it?", "\"No, that alone is not fraud. What matters is the statement that induced the deposit, and here the statement about the shingles was false.\""), .cross("Storm demand strained many roofing companies that spring, didn't it?", "\"Yes. Many had delays and supply problems. Most of them did not send a photo of someone else's pallets.\"")],
        defenseRole: "{DL}'s crew foreman",
        defenseExam: [.direct("What is your role at {D}'s company?", "\"I am the crew foreman. I run the crews on the roofs, schedule jobs with {D}, and order the day-to-day supplies.\""), .direct("What happened to the crews after the supplier account froze?", "\"We could not get shingles. We sat on jobs for weeks, and some of our crew left for other companies. It was a bad stretch.\""), .direct("Was {D} hiding from customers?", "\"No. {D} was at the shop every day, on the phone, and trying to get materials. I saw {D} work long hours.\""), .direct("How did {D} talk about the delay?", "\"With worry. {D} said the account would reopen and that we would catch up. I believed it, and I think {D} did as well.\""), .direct("What did you do when you learned the deposits had been spent?", "\"I was upset. I asked {D} what was going on, and {D} told me the money went to keep things going. We both felt awful.\""), .direct("What kind of boss is {D}?", "\"Fair and hard-working. {D} paid us even when money was tight, and I have never seen {D} cut corners on a roof.\""), .cross("You never went to the supplier yard yourself, did you?", "\"No. I never went to look at any pallets. {D} handled the supplier account.\""), .cross("You do not know what {D} told {V}, do you?", "\"No. I was on the roofs. I do not know what was said or sent to homeowners.\""), .cross("You knew the supplier account was frozen, didn't you?", "\"Yes. We all did, because we could not get shingles. It was the reason the crews were idle.\""), .cross("You cannot say where {V}'s deposit went, can you?", "\"No. I do not see the books. I only know what {D} told me about keeping the company going.\""), .cross("You would want to help your boss, wouldn't you?", "\"I would. But I am telling you what I saw, and I want what is true to come out.\"")],
        theory: ("{D} sent a photo of someone else's pallets to get {V}'s deposit.", "A good roofer swamped by storm demand and a frozen account."),
        allocution: "\"I sent a photo that I should not have sent. I will pay every family.\"",
        truths: ("{DL} bought a new boat motor three days after {V}'s deposit cleared.", "{DL} had been told by a salesman that the supplier hold would lift within two days."),
        defendant: [.direct("Why did you send {V} a photo of shingle pallets?", "\"I thought the supplier hold would lift in a day or two. I wanted to show {V} the work was moving, and I used a photo from another job.\""), .direct("Whose pallets were in the photo?", "\"Another job's. I said they were staged for {V}. That was not true, and I should not have said it.\""), .direct("What did you do with {V}'s deposit?", "\"I paid fuel and a truck note, and I refunded a past customer. I was trying to keep the company alive, and I know that is not what the money was for.\""), .direct("What was going on with your company that spring?", "\"The hailstorm brought more calls than we could handle. A bank error on a big payment froze my supplier account, and everything snowballed.\""), .direct("Did you intend to finish {V}'s roof?", "\"Yes. I fully planned to. I kept thinking the account would reopen and we would catch up. I never meant to cheat anyone.\""), .direct("What have you done since?", "\"I signed a repayment plan with {V} and started to return what I owe. I am working to make the other homeowners whole as well.\""), .cross("You did not tell {V} the job was delayed at first, did you?", "\"Not at first. I was embarrassed. I kept hoping to fix it quietly, and I should have called right away.\""), .cross("You bought a boat motor three days after {V}'s deposit cleared, didn't you?", "\"Yes. I had planned it for a while. The timing looks terrible, and I should have held off.\""), .cross("A supplier salesperson told you the hold would lift in two days, didn't they?", "\"Someone at the supplier said it might lift in a couple of days. I relied on that and it was wrong.\""), .cross("You used the deposit for things other than {V}'s roof, didn't you?", "\"Yes. I did. I paid other bills with it. That was a serious mistake.\""), .cross("The shingles in the photo were not {V}'s, were they?", "\"No. They were another job's. I should not have sent that photo.\"")],
        openings: ("After a spring hailstorm, {D} took deposits from five homeowners totaling $52,000. {V} paid $12,800 after {D} sent a photo of shingle pallets that belonged to another job.", "{D} was a good roofer drowned by storm demand and a frozen supplier account. {D} never meant to cheat anyone and signed a plan to repay."),
        closings: ("A photo of someone else's shingles, a supplier ledger with no order, and a deposit spent on fuel and a truck note. {V} was told something that was not true.", "{D} built a good record over six years and was swamped by a storm and a bank error. A frozen account is why the roofs were not done."),
        timeline: [(-70, "The hailstorm; calls pour in."), (-45, "The supplier puts {DL}'s account on hold."), (0, "{V} pays $12,800 after the photo."), (60, "{V} learns no shingles were ordered."), (95, "{DL} is charged.")],
        identified: "{DL} sent the photo and text to {V}.",
        aggravating: ["The offense was part of a pattern affecting five households"],
        mitigating: ["{DL} had operated a legitimate business for years", "{DL} made partial restitution before charges were filed"],
        mood: .divided,
        impact: "We lived under a blue tarp for four months.",
        doctrines: ["burdenOfProof"])

    static let flagTheftV1 = SmallCases.make(
        key: "story.flagTheft",
        category: .property,
        headlines: ["Veteran's Flag and Pole Torn From Lawn Bracket", "Porch Camera Catches Daytime Grab at Memorial Home"],
        law: "misdLarceny",
        spec: "Stole a flag and wall-mounted flagpole valued at $210 belonging to {V}, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "{V}, a retired Army veteran, came home on {DATE} to find the flag and wall-mounted pole gone from {V.his} porch column. A doorbell camera showed a young person in a ball cap unscrew the bracket at 4 p.m. The flag, with {V}'s unit patch sewn in the corner, was later found in {D}'s dorm closet. {DL} says it was a fraternity scavenger hunt item and a friend took it.",
        state: [E(.video, 3, "Doorbell Camera", "A person in a ball cap unscrews the pole bracket and walks away with it."), E(.physical, 2, "The Flag", "{V}'s flag with the patch, found in {D}'s closet.", .search)],
        defense: [E(.statement, 1, "Scavenger Hunt", "{DL} says a friend handed over the flag as a hunt item.")],
        role: "Campus police officer",
        exam: [.direct("What is your job with campus police?", "\"I am a campus police officer. I take reports of thefts and disturbances in the dorms and the surrounding area, and I follow up with the local sheriff.\""), .direct("Where was the flag found?", "\"In {D}'s dorm closet, folded on a shelf. It had {V}'s unit patch sewn in one corner, which {V} had described in the report.\""), .direct("What did the doorbell camera show?", "\"A young person in a ball cap using a screwdriver to unscrew the bracket at about 4 p.m. and walking away with the pole and flag.\""), .direct("What else was found in {D}'s room?", "\"The ball cap that matched the one in the video, hanging on a hook. We photographed it and took it into evidence.\""), .direct("What did {D} say when you asked about the flag?", "\"That it was part of a fraternity scavenger hunt, and a friend dropped it off. {D} said {D.he} did not take it from the porch.\""), .direct("How did you trace the flag to the dorm?", "\"A resident of the building mentioned a flag on a pole in a closet. We got a warrant and found it where the resident said.\""), .cross("The person in the video is mostly hidden by the cap, isn't that so?", "\"Yes. The face is mostly hidden. I cannot say from the video that the person is {D}.\""), .cross("{D} cooperated from the beginning, didn't {D.he}?", "\"Yes. {D} let us in, showed us the closet, and answered questions. {D} did not try to hide the flag.\""), .cross("A scavenger hunt list did exist, didn't it?", "\"Yes. We saw a list with a flag on it. A friend's name was on the pickup line for that item.\""), .cross("Caps like that one are common among students, aren't they?", "\"Yes. Many students wear similar caps. I would not rely on the cap alone.\""), .cross("The flag was not damaged or hidden, was it?", "\"No. It was folded and clean. It was not damaged, and it was in an ordinary place.\"")],
        theory: ("{D} took a veteran's flag from a porch.", "A hunt item handed over by a friend."),
        allocution: "\"I never should have kept it.\"",
        truths: ("The ball cap in the video was found hanging in {DL}'s room.", "The hunt list was real, and a friend's name was on the pole's pick-up line."),
        defendant: [.direct("Did you take the flag from {V}'s porch?", "\"No. I did not. I was not at that house, and I did not unscrew any bracket or touch the pole.\""), .direct("How did the flag end up in your closet?", "\"A friend dropped it off as a scavenger hunt item. I put it on the shelf and meant to return it when the hunt was over.\""), .direct("What do you know about the hunt?", "\"It was a fraternity game with a list of items. We had a few days to collect things and bring them back. I thought it was all harmless.\""), .direct("Why did you have the ball cap?", "\"It is mine and I wear it all the time. It hangs on a hook in my room. I did not wear it to anyone's house.\""), .direct("Did you know the flag belonged to a veteran?", "\"I noticed the patch when I opened the bag. I did not know whose it was or where it came from, and I felt bad.\""), .direct("What did you do when the officer came?", "\"I took the officer to the closet and gave it back. I told the officer who left it. I wanted it returned to the owner.\""), .cross("You saw the unit patch and did not return the flag, did you?", "\"I saw it. I thought I would return it after the hunt ended. I should have taken it back right away.\""), .cross("The ball cap in the video matches the one in your room, doesn't it?", "\"It looks similar. Many people have that kind of cap. I was not on that porch.\""), .cross("You did not ask your friend where the flag came from, did you?", "\"No. I assumed it came from a store or a donation. I should have asked.\""), .cross("You kept it in a closet and did not take it back, did you?", "\"Yes. I did, and I regret it. It was wrong to keep it even for a few days.\""), .cross("Your friend's name was on the pickup line, wasn't it?", "\"Yes. I told the officer the name. I did not take the flag, and I do not know who did.\"")],
        openings: ("{V}, a retired Army veteran, came home to find the flag and pole gone from {V.his} porch. A doorbell camera showed a person in a ball cap taking it, and the flag was found in {D}'s dorm closet.", "{D} says a friend dropped the flag off for a scavenger hunt. {D} did not take it from the porch and returned it as soon as an officer asked."),
        closings: ("A ball cap in the video, the same cap in {D}'s room, and the flag with {V}'s patch in {D}'s closet. {D} kept a veteran's flag.", "The face in the video is hidden, a scavenger hunt list was real, and {D} handed over the flag at once. A game that went too far is not a theft."),
        timeline: [(0, "4 p.m.: the pole is unscrewed."), (0, "6 p.m.: {V} reviews the doorbell camera."), (4, "Campus police find the flag in {DL}'s closet.")],
        identified: "A doorbell camera and a campus tip.",
        mood: .wantsConviction,
        genders: ["V": .male])

    static let tireIronAssaultV1 = SmallCases.make(
        key: "story.tireIronAssault",
        category: .violent,
        headlines: ["Roadside Argument Over Flat Tire Ends With Broken Arm", "Gas Station Camera Records Swing With Lug Wrench"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon, a tire iron, inflicting serious injury, on {DATE}.",
        ages: 23...58,
        victim: true,
        summary: "On {DATE}, a pickup blocked a gas station air pump while {D} waited. After words, {V} was hit on the upper arm with a tire iron and needed a plate and screws. A clerk saw {D} pull the iron from a truck bed. {DL} says {V} came at {D.him} with clenched fists and a shove.",
        state: [E(.video, 3, "Gas Station Camera", "{D} takes a tire iron from a truck bed and swings it at {V}."), E(.forensic, 3, "Medical Records", "A broken upper arm treated with a plate and screws."), E(.statement, 1, "911 Call", "The clerk reports someone swinging an iron.")],
        defense: [E(.statement, 1, "Came At Me", "{DL} says {V} rushed {D.him}.")],
        role: "Gas station clerk",
        exam: [.direct("What is your job at the gas station?", "\"I am the clerk. I run the register, watch the lot through the front window, and call for help when there is a problem outside.\""), .direct("What did you see on {DATE}?", "\"A pickup was blocking the air pump while {D} waited. There were words between {D} and {V}, and then {D} took a tire iron out of a truck bed.\""), .direct("What did {D} do with the tire iron?", "\"Swung it at {V}'s upper arm. It was one hard swing. {V} dropped and held the arm, and {D} stood for a moment and then stepped back.\""), .direct("What did you hear before the swing?", "\"Loud shouting from both of them. I could not make out the words. It was a quarrel over the pump, and it got heated fast.\""), .direct("What did you do after you saw it?", "\"I called 911 and said someone had swung an iron at another person. I stayed at the register and watched until the deputies came.\""), .direct("What was {V}'s injury?", "\"A broken upper arm. I learned later that {V} needed a plate and screws. {V} was in pain and could not use the arm.\""), .cross("{V} stepped toward {D} before the swing, didn't {V}?", "\"One step, maybe. I saw movement, and I cannot say how close {V} came. The camera may show it better.\""), .cross("{D} did not back away first, did {D.he}?", "\"No. {D} stood there. I did not see {D} step back before reaching into the truck bed.\""), .cross("There was a closer door {D} could have gone to, wasn't there?", "\"The station door was closer than the truck. I do not know why {D} went to the truck instead.\""), .cross("The shouting was from both sides, wasn't it?", "\"Yes. Both were loud. I cannot say who started it, and I did not hear a clear threat from either.\""), .cross("You did not see {V} shove {D}, did you?", "\"I saw some pushing, but I was not sure who did what first. I could not tell from where I stood.\"")],
        defenseRole: "Defendant's cousin",
        defenseExam: [.direct("How are you related to {D}?", "\"{D} is my cousin. We grew up near each other and see each other often. I was with {D} that day.\""), .direct("Where were you standing during the argument?", "\"By the ice machine, about twenty feet from the pump. I had a clear view of both of them, and I heard the shouting.\""), .direct("What did you see {V} do?", "\"{V} pushed {D} before the swing. {V} stepped in with both hands and shoved {D} in the chest, and {D} stumbled back.\""), .direct("How did {D} react to the push?", "\"{D} looked startled. {D} was backed against the truck and grabbed the nearest thing. It all happened in a second.\""), .direct("What kind of person is {D}?", "\"Not violent. {D} gets loud, but I have never seen {D} hit anyone. I was shocked by what happened.\""), .direct("What did {D} do after the swing?", "\"{D} stood still and looked horrified. {D} said sorry and asked if {V} needed help, and waited for the deputies.\""), .cross("You are {D}'s cousin, aren't you?", "\"Yes. I love {D}. I am telling you what I saw, not what I wish I had seen.\""), .cross("You did not see who shouted first, did you?", "\"No. I heard the shouting when I turned my head. I cannot say who started it.\""), .cross("You saw {V} push {D} only once, didn't you?", "\"I saw it once. It was quick. There may have been more that I missed.\""), .cross("{D} had a way to leave before the swing, didn't {D.he}?", "\"Maybe. {D} was against the truck. I do not know what else {D} could have done in that second.\""), .cross("You do not know what was in {D}'s mind, do you?", "\"No. I only know what I saw and what I heard. I cannot see inside anyone's mind.\"")],
        theory: ("{D} swung an iron at a driver.", "A swing in fear of a charging stranger."),
        allocution: "\"I am sorry that {V} was hurt.\"",
        truths: ("{DL} walked past a closer door to get to the truck bed.", "The camera angle shows {V}'s fists were clenched and raised before the swing."),
        defendant: [.direct("Did you swing the tire iron at {V}?", "\"Yes. I did. I was scared, and I swung once. I wish I had walked away, and I think about it every day.\""), .direct("Why did you swing?", "\"{V} was coming at me with clenched fists and a shove. I did not know what {V} would do next, and I grabbed what was at hand.\""), .direct("Why did you get the tire iron from the truck bed?", "\"It was the nearest thing. I turned without weighing anything. I turned and grabbed it, and I did not plan to hit anyone.\""), .direct("What was the argument about?", "\"A pickup parked at the air pump for a long time while I waited with a flat. I asked politely, and then I got angry.\""), .direct("Did you shout at {V} first?", "\"A little. I raised my voice because I was frustrated. I know it did not help the situation.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to break your arm. I will do what I can to make it right.\""), .cross("You walked past the station door to get to your truck, didn't you?", "\"Yes, without a second thought. I know it looks like I planned it, but I did not.\""), .cross("{V}'s fists were clenched and raised before you swung, weren't they?", "\"The video shows that. They were raised, and I took it as a threat. I did not wait to see.\""), .cross("You shouted at {V} before the swing, didn't you?", "\"Yes. I was upset about the pump. I raised my voice, and I should not have.\""), .cross("You could have walked away, couldn't you?", "\"Yes. I could have gone into the station or driven off. I chose to reach for the iron.\""), .cross("You swung a tire iron at a person's arm, didn't you?", "\"I did. I was afraid, but I know it was a serious thing to do. It hurt {V} badly.\"")],
        openings: ("A pickup blocked a gas station air pump, words were exchanged, and {D} pulled a tire iron from a truck bed and swung it at {V}'s arm. {V} needed a plate and screws.", "{D} was backed against a truck when a stranger rushed forward with a shove. {D} swung in fear in one second and is sorry."),
        closings: ("The camera shows {D} walking past a closer door, taking the iron from the truck bed, and swinging it at {V}'s arm. {V} was left with a broken arm.", "{V}'s fists were raised and a shove came first. {D} swung out of fear, not out of anger, and that is the difference between a crime and a reaction."),
        timeline: [(0, "6:50 p.m.: the air pump dispute."), (0, "6:54 p.m.: {DL} goes to the truck."), (0, "6:55 p.m.: the swing."), (0, "7:15 p.m.: deputies arrive.")],
        identified: "A clerk and the station camera.",
        aggravating: ["The defendant was armed with a deadly weapon at the time of the crime"],
        mood: .divided,
        doctrines: ["selfDefense"],
        genders: ["V": .male])

    static let caregiverAccountV1 = SmallCases.make(
        key: "story.caregiverAccount",
        category: .whiteCollar,
        headlines: ["Companion Aide Accused of Draining 88-Year-Old's Retirement Account", "Wire Transfers and a Motorhome Lead to Exploitation Case"],
        law: "exploitationElder",
        threshold: 4,
        spec: "Knowingly exploited {V}, an older adult, by using {V.his} funds for {DL}'s own benefit through deception and undue influence.",
        ages: 29...52,
        victim: true,
        summary: "{D} worked as a live-in companion for {V}, 88, a widowed retired postmaster, for about three years. Over twenty months, $54,000 left {V}'s retirement account through wire transfers to {D}'s bank, a motorhome titled to {D}, and a new credit line opened in {V}'s name. A bank teller flagged a wire around {DATE} and called {V}'s son. {DL} says {V} loved to give, wired the money on {V.his} own, and often said {D} was a daughter to {V.him}. {V} is sharp on some days and confused on others.",
        state: [E(.document, 3, "Wire Records", "Seven wires from {V}'s account to {D}'s account, signed with {V}'s signature."), E(.document, 3, "Motorhome Title", "A $31,000 motorhome titled to {D}, paid in full from {V}'s funds.", .search), E(.statement, 2, "Bank Teller", "{D} stood by {V} at the window and answered the questions.")],
        defense: [E(.document, 2, "Gift Letters", "Notes in {V}'s handwriting saying the wires were gifts."), E(.statement, 1, "Doctor's Note", "{V}'s doctor wrote that {V} was able to make decisions on some days.")],
        role: "Bank teller",
        exam: [.direct("What caught your attention about {V}'s wire?", "\"A large wire request, and {D} did most of the talking for {V}. {V} looked to {D} before answering my questions, which is unusual.\""), .direct("What is {V}'s situation as you know it?", "\"{V} is 88, a widowed retired postmaster, who has had {D} as a live-in companion for about three years. {V} has good days and confused days.\""), .direct("How many wires went to {D}'s bank?", "\"Seven over twenty months, along with a motorhome titled to {D} and a new credit line opened in {V}'s name. The total was about $54,000.\""), .direct("What did {V} say about the transfers when you asked?", "\"Once, quietly, {V} said it was a gift. I asked again, and {V} looked at {D} and nodded. I did not feel {V} was sure.\""), .direct("What did you do after you flagged the wire?", "\"I told my supervisor and called {V}'s family member listed on the account. We held the wire until the family could speak with {V}.\""), .direct("What notes did the bank find from {V}?", "\"Gift letters in {V}'s handwriting saying the wires were gifts. Two of them looked copied from typed drafts, and they were dated near the wires.\""), .cross("{V} signed every slip, didn't {V}?", "\"Yes. Each wire request was signed in {V}'s hand. I cannot say that {V} did not sign, only that {V} looked unsure.\""), .cross("{V} does have days when {V} is sharp, doesn't {V}?", "\"I understand so. The doctor's note says {V} can make decisions on some days. I did not know which kind of day it was.\""), .cross("Customers often bring a trusted companion to the window, don't they?", "\"Yes. It is common. A companion who answers questions for the customer is what concerned me.\""), .cross("{V} said it was a gift, didn't {V}?", "\"Once, quietly. I wrote that in my notes. I did not hear any other explanation from {V}.\""), .cross("You did not interview {D} yourself, did you?", "\"I spoke briefly with {D} at the window. I did not interview {D} beyond that.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("How do you know {V} and {D}?", "\"I am their neighbor. I have lived next door to {V} for many years, and I saw {D} nearly every day for the past three years.\""), .direct("How did {V} treat {D}?", "\"Like family. They baked together, watched the ballgame on the porch, and teased each other. {V} was happier after {D} came.\""), .direct("What did {V} say about {D} to you?", "\"That {D} was the best thing to happen in years. {V} said it more than once, and I believed it.\""), .direct("Did {V} talk about giving things to {D}?", "\"Yes. {V} said {V.he} wanted {D} to have a home of {D.his} own, and talked about a motorhome a long time ago.\""), .direct("How was {V}'s memory?", "\"Good some days and foggy on others. On the good days, {V} told stories from the post office with great detail.\""), .direct("Did {V}'s family visit?", "\"Rarely. A family member came a few times a year. {D} was the one who was there every day.\""), .cross("You did not see the bank transactions, did you?", "\"No. I know nothing about the wires or the credit line. I only know what I saw between {V} and {D} at home.\""), .cross("{V} was confused on some days, wasn't {V}?", "\"Yes. That is true. I do not know what kind of day it was when each wire was sent.\""), .cross("You like {D}, don't you?", "\"Yes. I do, and I try to be fair. I cannot say what is in the books.\""), .cross("You did not hear {V} plan the motorhome gift, did you?", "\"I heard {V} mention it once. I did not hear details, and I cannot tell you when it was decided.\""), .cross("You cannot say whether {D} ever suggested the gifts, can you?", "\"No. I never heard {D} ask. I also was not present for every conversation.\"")],
        theory: ("{D} used trust and a failing mind to take $54,000.", "A cherished caretaker who was given gifts freely."),
        allocution: "\"I loved {V}. I never meant to take advantage.\"",
        truths: ("{DL} typed two of the so-called gift letters on {D.his} own phone and had {V} copy them by hand.", "{V}'s lawyer says {V} planned the motorhome gift a year before the first wire."),
        defendant: [.direct("Did you ask {V} for the money?", "\"No. {V} offered. {V} often said I was like family and wanted me to have something to show for the years we spent together.\""), .direct("What about the motorhome?", "\"{V} wanted me to have a home of my own. We talked about it for a year, and {V} told the lawyer about the plan before any wire.\""), .direct("Who went to the bank with {V}?", "\"I drove {V} and stood nearby. I did not tell {V} what to say. I answered questions when {V} looked at me, and I should have kept quiet.\""), .direct("Who wrote the gift letters?", "\"I helped with the wording. {V} copied them by hand. I thought it would make the bank more comfortable, and I know how it looks.\""), .direct("How was your life with {V}?", "\"Close. We cooked, watched ballgames, and told stories. I loved {V}, and I was proud to care for {V} every day.\""), .direct("What would you say to {V}'s family?", "\"That I am sorry for the pain this caused. I did not take advantage, and I wish we had talked about money more openly.\""), .cross("You typed two of the gift letters on your phone, didn't you?", "\"Yes. I typed them so {V} could copy them. I was trying to help, and I know that looks like I was writing {V}'s words.\""), .cross("You stood next to {V} at the bank window, didn't you?", "\"Yes. I was there to help. I did not try to answer for {V}, but I know it may have seemed that way.\""), .cross("A motorhome and seven wires came to you, didn't they?", "\"Yes. They were gifts. I did not ask for them, and I did not think there was anything wrong.\""), .cross("A credit line was opened in {V}'s name, wasn't it?", "\"Yes. I thought {V} agreed. I did not check the paperwork, and I should have.\""), .cross("{V} is confused on some days, isn't {V}?", "\"On some days. I tried to help on those days, and I never took advantage of it.\"")],
        openings: ("{D} lived with {V}, 88, as a companion for three years. Over twenty months $54,000 left {V}'s account for wires to {D}, a motorhome titled to {D}, and a credit line in {V}'s name.", "{V} loved {D} like family and gave freely. A cherished caretaker is not a thief, and {V} wrote the gift letters in {V.his} own hand."),
        closings: ("Seven wires, a motorhome, a new credit line, two letters typed on {D}'s phone, and a teller who saw {V} look to {D} for answers. This was not freely given.", "{V} planned the gift a year earlier and told a lawyer. A caretaker who was loved and given gifts is not a thief."),
        timeline: [(-780, "{D} moves in as companion."), (-600, "The first wire."), (-20, "The motorhome title is transferred."), (0, "The teller calls {V}'s son."), (40, "{DL} is charged.")],
        identified: "A bank teller's alert.",
        aggravating: ["The victim was very old", "The defendant took advantage of a position of trust or confidence"],
        mitigating: ["No prior criminal record"],
        mood: .divided,
        impact: "I feel foolish and I miss my savings.",
        genders: ["D": .female, "V": .female])

    static let deerStandTrespassV1 = SmallCases.make(
        key: "story.deerStandTrespass",
        category: .property,
        headlines: ["Hunter Pulled From Climbing Stand on Posted Farm Tract", "Landowner's Game Camera Catches Predawn Intruder"],
