        defendant: [.direct("Whose wheels did you think they were?", "\"The trader's. I thought they were the trader's to give. I did not ask where they came from, and I should have.\""), .direct("What did you give for them?", "\"A day of welding, worth about $200 of work. We agreed on it at my shop, and I finished the job that afternoon.\""), .direct("Who was the trader?", "\"Someone named Tony. I never got a last name. Tony came by my shop a few times and had offered work and parts before.\""), .direct("Why did you keep the wheels on a trailer in plain view?", "\"I did not think there was anything to hide. I planned to sell them or use them, and I did not think anyone would claim them.\""), .direct("Did you search online for a buyer for the rims?", "\"Yes. A couple of days after I got them. I wanted to see what they were worth. I had no idea where they really came from.\""), .direct("What did you do when the deputy came?", "\"I showed the deputy the wheels and told the story right away. I did not argue, and I gave the deputy everything I knew.\""), .cross("You never asked Tony where the wheels came from, did you?", "\"No. I should have. I took the trade and moved on, and I did not ask.\""), .cross("You searched online for a buyer two days after the theft, didn't you?", "\"Yes. That was after I got the wheels. I understand the timing looks bad.\""), .cross("You cannot give Tony's last name, can you?", "\"No. I only know the first name. I wish I knew more.\""), .cross("A set of rims is worth more than a day of welding, isn't it?", "\"Yes. I knew I was getting a good deal. The bargain never made me stop and ask questions.\""), .cross("You did not report the trade to anyone, did you?", "\"No. It was a private trade. I did not see any reason to report it.\"")],
        openings: ("{V}'s SUV was left on jack stands with its wheels gone. Ten days later, {V} spotted rims with a distinctive chip on a trailer at {D}'s home, and a deputy matched the serial marks.", "{D} traded a day of welding for a set of wheels. {D} had no idea where those wheels came from and kept them in plain view."),
        closings: ("The invoice, the serial marks, and a chip on the rims all match {V}'s wheels, which sat on {D}'s trailer. {D} cannot name the trader beyond a first name.", "The tradesman who traded the wheels later admitted to other wheel thefts and said {D} did not know. A buyer who did not know is not a thief."),
        timeline: [(0, "Overnight: the wheels are taken."), (10, "{V} spots the rims."), (10, "A deputy matches the marks."), (11, "{V} gets the wheels back.")],
        identified: "{V}'s sighting and a deputy's check.",
        genders: ["D": .male, "V": .female])

