    static let vendingMachinePryV1 = SmallCases.make(
        key: "story.vendingMachinePry",
        category: .property,
        headlines: ["Laundromat Snack Machine Pried Open Overnight", "Coin Tray Cracked by Crowbar, Suspect Stopped With Change"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a snack vending machine, causing damage of $590, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "{V}, a vending route owner, found a snack machine outside a laundromat with its door bent and coin tray forced on {DATE}. A camera on the laundromat showed a figure with a pry bar at the machine at 2:10 a.m. {D} was stopped a few blocks away with a tin of $44 in coins and a pry bar. {DL} says {D.he} found the coins in a laundry cart and uses the pry bar for work.",
        state: [E(.video, 3, "Laundromat Camera", "A figure pries at the machine door at 2:10 a.m."), E(.physical, 2, "Coins and Pry Bar", "$44 in coins in a tin and a pry bar with fresh paint flakes in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Work Tool", "{DL} says the pry bar is for {D.his} flooring job.")],
        role: "Vending route owner",
        exam: [.direct("What do you do for a living?", "\"I own a vending route. I stock snack and drink machines at businesses around town, collect the coins, and keep the machines repaired.\""), .direct("What did you find at the laundromat on {DATE}?", "\"The door of the snack machine was bent back and the coin tray had been forced open. The lock plate was cracked and the tray was empty.\""), .direct("What did the laundromat camera show?", "\"A figure in a hood prying at the machine door with a bar at 2:10 in the morning. The figure worked at it for several minutes.\""), .direct("How much damage did the machine suffer?", "\"The door and the lock plate had to be replaced. The repair cost several hundred dollars, and I lost a day of sales while it was out.\""), .direct("How much cash do you usually leave in a machine like that?", "\"Not much overnight, because I collect often. A day or two of coins and small bills. The theft was far less than the damage.\""), .direct("What did deputies tell you about the person they stopped?", "\"They stopped {D} a few blocks away with a tin of $44 in coins and a pry bar in the car. The deputies told me that afterward.\""), .cross("The face on the video is hidden by a hood, isn't it?", "\"Yes. I could not tell who it was. The hood was up the whole time, and the camera did not catch a face.\""), .cross("Many people carry a pry bar, don't they?", "\"Plenty do. Tradesmen carry them all the time. I do not assume anyone with one is a thief.\""), .cross("Coins are left in laundry carts at laundromats, aren't they?", "\"They are. Customers drop coins and forget them. I have found some myself in the carts and under machines.\""), .cross("The amount in the tin was small, wasn't it?", "\"$44. That is not a lot compared with the damage. A machine that has been forced often holds more.\""), .cross("You did not see who forced the machine, did you?", "\"No. I saw it only on the camera the next day. I was not there at 2 a.m.\"")],
        theory: ("{D} pried open a machine for the change.", "A worker with a tool and found coins."),
        allocution: "\"I was low on money and made a bad choice.\"",
        truths: ("{DL}'s hood in the car matched the one in the video.", "{DL}'s boss says {DL} was on a job site until midnight and the pry bar was marked with the company name."),
        defendant: [.direct("Did you pry open the snack machine?", "\"No. I did not. I have never forced a machine. I was out walking that night and I did not go near the laundromat.\""), .direct("Where did the $44 in coins come from?", "\"I found it in a laundry cart outside the laundromat earlier that evening. I scooped the coins into a tin because I thought they were abandoned.\""), .direct("Why were you out at 2:30 in the morning?", "\"I could not sleep. I walk when I cannot sleep, and I carry my work tools in my car because I never know when I will need them.\""), .direct("What is the pry bar for?", "\"My flooring job. I pull up old planks and nails with it. It has the company name painted on it, and my boss can say it is ours.\""), .direct("What were you doing earlier that night?", "\"I was on a job site until midnight. My boss can say so. I drove home and then went out because I was restless.\""), .direct("What did you tell the deputies?", "\"Everything. I told them about the coins and the tool, and I gave them my boss's number. I did not try to hide anything.\""), .cross("The hood in your car matches the one in the video, doesn't it?", "\"It looks similar. A lot of hoods look the same. I wear mine all the time, and I was not at the laundromat.\""), .cross("You were a few blocks from the laundromat with a pry bar, weren't you?", "\"Yes. I was walking home. It looks bad, and I understand why.\""), .cross("You carry a pry bar in your car, don't you?", "\"Yes. It is for work. I forget it is there, and I know how it looks.\""), .cross("You had $44 in coins in a tin, didn't you?", "\"Yes. I found them in a cart. I should have left them or turned them in.\""), .cross("No one can say you were on a job until midnight except your boss, can they?", "\"My boss and the people on the job. The site was locked up at midnight, and a security log may show it.\"")],
        openings: ("A snack machine outside a laundromat had its door bent and its coin tray forced at 2:10 a.m. {D} was stopped a few blocks away with a tin of $44 in coins and a pry bar.", "{D} is a flooring worker with a tool from the job and coins found in a laundry cart. A hood and a pry bar are not proof of anything."),
        closings: ("A figure with a pry bar at 2:10 a.m., and a person stopped nearby with a pry bar and a tin of coins. The hood in the car matches the hood on camera.", "The video shows a hood and a tool that thousands of people own. {D} was on a job until midnight and found the coins in a cart."),
        timeline: [(0, "2:10 a.m.: the machine is forced."), (0, "2:35 a.m.: a deputy stops {DL}."), (0, "8 a.m.: {V} finds the damage.")],
        identified: "The laundromat camera and a stop.",
        genders: ["D": .male])

    static let roommateStabbingV1 = SmallCases.make(
        key: "story.roommateStabbing",
