        state: [E(.video, 3, "Doorbell Camera", "{D} leaves on foot with a backpack at 12:05 a.m."), E(.forensic, 3, "Knife in Drain", "A kitchen knife with {V}'s blood and a partial print on the handle.", .search), E(.statement, 2, "Neighbor", "Shouting over a utility bill just before midnight.")],
        defense: [E(.statement, 1, "Left First", "{DL} says {D.he} left in anger before anything happened.")],
        role: "Police detective",
        exam: [.direct("What did you find in the kitchen of the duplex on {DATE}?", "\"{V} was dead on the kitchen floor from multiple stab wounds. There was a lot of blood, and no sign of forced entry at either door.\""), .direct("What did a neighbor tell you about that night?", "\"The neighbor heard shouting about the power bill just before midnight. It was loud and angry, and then it stopped. The neighbor did not see anyone.\""), .direct("What did the next-door doorbell camera show?", "\"{D} leaving on foot at 12:05 a.m. carrying a backpack. {D} walked quickly and did not look back, according to the video.\""), .direct("What was found a block away?", "\"A kitchen knife in a storm drain. It matched the set from the duplex kitchen, and it had traces consistent with blood.\""), .direct("What did you find in {D}'s backpack?", "\"A bag of wet clothes. They were damp when we recovered them, and they were being tested. {D} also had a change of clothes.\""), .direct("What did you learn about the knife's fingerprints?", "\"A partial print on the handle. It was a smudge, and no examiner could attribute it to {D} or to anyone else.\""), .cross("The print on the knife was only a smudge, wasn't it?", "\"Yes. It was partial and not suitable for a comparison. I cannot connect it to {D}.\""), .cross("There was a third housemate, wasn't there?", "\"Yes. A third housemate lived there but was away that week. That housemate has an alibi.\""), .cross("{D} came back to the duplex and called for help, didn't {D.he}?", "\"{D} returned later and a friend was called. I understand {D} was shaken when we arrived.\""), .cross("Shouting does not prove a killing, does it?", "\"No. A shouting match about a bill is common. I do not take shouting alone as proof of a killing.\""), .cross("The knife came from the shared kitchen, didn't it?", "\"Yes. It was one of the kitchen knives. Anyone in the house had access to it.\"")],
        defenseRole: "Defendant's friend",
        defenseExam: [.direct("How do you know {D}?", "\"I am {D}'s friend. We have known each other for years, and I see {D} most weeks.\""), .direct("When did {D} call you that night?", "\"Around 1 a.m. {D} sounded upset and shaky, and said something was wrong at the house.\""), .direct("What did {D} say?", "\"That {V} was hurt and that {D} did not know what to do. I told {D} to call 911 right away and I would meet {D} there.\""), .direct("How did {D} seem?", "\"Shaken. {D} was crying and could barely get words out. I have never heard {D} that upset.\""), .direct("Had {D} talked about {V} before?", "\"Yes. They argued about bills sometimes. {D} was frustrated, but never talked about hurting {V}.\""), .direct("What kind of person is {D}?", "\"Gentle. I have never seen {D} in a fight. {D} would walk away from conflict, and that is what I expected that night.\""), .cross("You were not at the duplex that night, were you?", "\"No. I was at home, and {D} called me. I only know what {D} told me.\""), .cross("You do not know what happened before the call, do you?", "\"No. I do not know what was said or done. I can only tell you how {D} sounded.\""), .cross("{D} had changed clothes before you saw {D}, hadn't {D.he}?", "\"I believe so. {D} had a dry shirt on when I met {D}. I did not ask why.\""), .cross("You are loyal to {D}, aren't you?", "\"Yes. I care about {D}, and I will say only what I know to be true.\""), .cross("You did not see {V} that night, did you?", "\"No. I never saw {V}. I was told by {D} and then by the deputies.\"")],
        theory: ("{D} killed {V} and left with the knife.", "A housemate who stormed out and found a body."),
        allocution: "\"I wish I had stayed.\"",
        truths: ("{DL} had changed clothes before the friend called and a bag of wet clothes was found in the backpack.", "The partial print on the knife was a smudge no examiner could attribute to {DL}."),
        defendant: [.direct("Did you hurt {V}?", "\"No. I did not. {V} was my housemate. We argued, and I left angry, and when I came back {V} was dead.\""), .direct("What was the argument about?", "\"The power bill. {V} thought I owed more. We both raised our voices, and I said I was done and needed to get out.\""), .direct("Why did you leave with a backpack?", "\"I planned to stay with a friend that night. I packed a few things and walked out. I needed to cool off.\""), .direct("Where did you go?", "\"I walked around for a while and then to a friend's place. I came back later to get something, and that is when I found {V}.\""), .direct("What did you do when you found {V}?", "\"I froze, and then I called a friend, who told me to call 911. I did, and I waited outside until the deputies arrived.\""), .direct("Why were there wet clothes in your backpack?", "\"I had gotten caught in the rain on my walk and changed at my friend's place. I stuffed the wet ones in the bag.\""), .cross("You were the last one seen leaving at 12:05, weren't you?", "\"Yes. The camera shows it. I did not hurt {V}, and I left before anything happened.\""), .cross("You changed your clothes before you called anyone, didn't you?", "\"I changed because I was wet from the rain. I did not think about it as anything else.\""), .cross("You and {V} were shouting just before you left, weren't you?", "\"Yes. We were both angry. It was about money, and I have never been violent.\""), .cross("The knife was found a block from the house, wasn't it?", "\"Yes. Someone else must have carried it there, because I did not take it.\""), .cross("You did not call 911 right away, did you?", "\"I called a friend first. I was in shock, and I did not know what to do.\"")],
        openings: ("{V} was found dead from stab wounds in a kitchen after a shouting match about the power bill. A camera showed {D}, {V}'s housemate, leaving on foot with a backpack, and a knife was in a drain nearby.", "{D} stormed out after an argument and came back to find {V} dead. A smudged print and a rainy walk are not proof of murder."),
        closings: ("A shouting match, a housemate leaving with a backpack at 12:05, a knife in a drain, and wet clothes in the bag. All of it fits {D}.", "A partial smudge on the knife, a third housemate, and a friend who heard {D} in tears. {D} walked into a nightmare and did not cause it."),
        timeline: [(0, "11:45 p.m.: the shouting over the bill."), (0, "12:05 a.m.: {DL} leaves with a backpack."), (1, "1 a.m.: {DL} calls a friend."), (1, "A knife is found in a storm drain.")],
        identified: "A doorbell camera and a knife in a drain.",
        aggravating: ["The offense involved a weapon"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "lesserIncluded"],
        genders: ["D": .male, "V": .male])

    static let shedBreakInV1 = SmallCases.make(
