        ages: 19...55,
        victim: true,
        summary: "{V} found the padlock cut on a backyard garden shed on {DATE}. A pole saw, a hedge trimmer and a cordless drill were missing. Two days later, a pawn shop logged a hedge trimmer matching {V}'s serial number, pawned by {D}, who lives around the corner. {DL} says {D.he} bought the trimmer for $30 from a coworker.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on a ticket for a hedge trimmer whose serial matches {V}'s manual."), E(.physical, 2, "Cut Padlock", "A padlock cut with bolt cutters, found in the grass.")],
        defense: [E(.statement, 1, "Coworker Sale", "{DL} says a coworker sold {D.him} the trimmer.")],
        role: "Pawn shop clerk",
        exam: [.direct("What is your job at the pawn shop?", "\"I am the clerk. I take items in, check serial numbers and IDs, and write tickets. I deal with customers every day.\""), .direct("Who pawned the hedge trimmer two days after the shed break-in?", "\"{D}. {D} handed me a license, and I wrote up a ticket for a hedge trimmer. I logged the serial number as I always do.\""), .direct("What did the serial number check show?", "\"It matched a theft report filed by {V}. The match came from the manual {V} had kept, which listed the same serial number.\""), .direct("How did {D} act at the counter?", "\"Calm. {D} chatted and signed the ticket without any hesitation. I noticed nothing out of the ordinary at the time.\""), .direct("How much did the shop pay for the trimmer?", "\"$30 for the trimmer. It was a modest amount, and {D} accepted it without negotiating.\""), .direct("What did you do when the check came back?", "\"I called the sheriff's office and held the trimmer. A deputy came and took it into evidence. I gave the deputy {D}'s ticket and ID.\""), .cross("{D} used a real ID, didn't {D.he}?", "\"Yes. {D} gave a state license and the address on it was real. It was not hidden or changed.\""), .cross("{D} did not seem nervous, did {D.he}?", "\"Not at all. {D} was relaxed. I would not have guessed anything was wrong.\""), .cross("People pawn items from coworkers all the time, don't they?", "\"Yes. Many items come through that way, and I cannot tell where each one came from.\""), .cross("You did not see {D} near the shed, did you?", "\"No. I have no knowledge of that. I only know what happened at my counter.\""), .cross("The trimmer was one among many common brands, wasn't it?", "\"It is a popular model. The serial number is what made the match, not the brand.\"")],
        theory: ("{D} cut into a shed and pawned the stolen trimmer.", "A buyer who never saw the shed."),
        allocution: "\"I should have checked where it came from.\"",
        truths: ("A pair of bolt cutters was in the bed of {DL}'s truck.", "The coworker was identified later and confirmed the sale for $30."),
        defendant: [.direct("Did you break into {V}'s shed?", "\"No. I never went near that shed. I did not cut the lock and I did not take anything from it.\""), .direct("Where did you get the hedge trimmer?", "\"From a coworker. I paid $30 for it at work, and I did not ask where it came from.\""), .direct("Why did you pawn it?", "\"I did not need it. I did not have a hedge, and I wanted some cash. I took it to the pawn shop around the corner.\""), .direct("Why did you use your own ID at the pawn shop?", "\"I had no reason to hide. I thought the trimmer was mine to sell, and I did not think anyone would claim it.\""), .direct("What did you do when the deputy contacted you?", "\"I told the deputy about my coworker and gave the name. The coworker confirmed the sale later.\""), .direct("What would you say to {V}?", "\"That I am sorry. I should have asked more questions before I bought and sold it. I did not mean to profit from a theft.\""), .cross("You own bolt cutters, don't you?", "\"Yes. I use them for my job. A lot of people who work in construction have a pair.\""), .cross("A pair of bolt cutters was in your truck bed, wasn't it?", "\"Yes. I keep them there. I did not use them on the shed.\""), .cross("You pawned the trimmer two days after the theft, didn't you?", "\"Yes. That is how it fell. I know the timing looks bad.\""), .cross("You paid $30 for a tool worth much more, didn't you?", "\"Yes. It was cheap. I should have asked why it was so cheap.\""), .cross("You did not ask your coworker where the trimmer came from, did you?", "\"No. I took the deal and moved on. I wish I had asked.\"")],
        openings: ("{V} found the padlock cut on a backyard shed. Two days later, {D} pawned a hedge trimmer with {V}'s serial number, and bolt cutters were in the bed of {D}'s truck.", "{D} bought a hedge trimmer for $30 from a coworker and pawned it under a real ID. A coworker confirmed the sale."),
        closings: ("A cut padlock, a serial number that matches, bolt cutters in {D}'s truck, and a trimmer pawned two days after the theft. The pieces point to {D}.", "{D} used a real ID and told the deputy about the coworker. The coworker confirmed it, and a buyer who did not know is not a burglar."),
        timeline: [(0, "Overnight: the padlock is cut."), (0, "Morning: {V} finds the shed open."), (2, "{DL} pawns the trimmer."), (3, "The pawn check flags the serial.")],
        identified: "A pawn shop serial check.",
        genders: ["D": .male])

