        defense: [E(.statement, 1, "Tire Jack", "{DL} says {V} swung a tire jack.")],
        role: "Police detective",
        exam: [.direct("What did the garage camera show after the concert?", "\"{V} and {D} arguing near a damaged bumper. {D} then thrust a blade twice at {V} and drove away from the parking deck.\""), .direct("What injuries did {V} suffer?", "\"A punctured lung and a cut to the liver. {V} needed emergency surgery and spent several days in intensive care.\""), .direct("What did you find in {D}'s car?", "\"A folding knife with blood on the blade. It was in the center console, and {D} handed it over when we stopped {D} later that night.\""), .direct("What did you learn about the argument?", "\"It was about a bumper that was damaged in the parking deck. {V} thought {D} had hit the car, and they began shouting.\""), .direct("What messages did {D} send before the concert ended?", "\"An hour before the stabbing, {D} texted that '{V} is going to pay for the bumper.' We found it when we read {D}'s phone.\""), .direct("How did the deputies reach {D}?", "\"The plate was on the garage camera. We traced it, went to {D}'s address, and found {D} at home with the knife in the car.\""), .cross("Something was at {V}'s side in the video, wasn't there?", "\"Yes. A long object, which may be a tire jack. The angle is unclear, and I cannot say what {V} did with it.\""), .cross("A second camera shows {V} lifting something, doesn't it?", "\"It shows {V} lifting the jack toward {D}. I have viewed that footage and I will say so.\""), .cross("{D} was cooperative when you found {D.him}, wasn't {D.he}?", "\"Yes. {D} handed over the knife and answered questions. {D.he} said {V} had come at {D.him} with a jack.\""), .cross("The two had argued loudly, hadn't they?", "\"Yes. Other concertgoers heard shouting. It was a heated argument over a bumper.\""), .cross("You did not see the stabbing yourself, did you?", "\"No. I rely on the cameras, the medical records, and the statements. I was not there.\"")],
        defenseRole: "Defendant's girlfriend",
        defenseExam: [.direct("How are you related to {D}?", "\"I am {D}'s partner. We have been together for about two years, and I was at the concert with {D}.\""), .direct("What did you see in the parking deck?", "\"{V} had a tire jack in {V}'s hand and was holding it up. {D} stepped back, and then everything happened very fast.\""), .direct("Where were you standing?", "\"About fifteen feet away, near our car. I could see both of them under the lights, and I heard the shouting.\""), .direct("How did {D} react when {V} raised the jack?", "\"{D} looked scared. {D} backed up against the pillar and pulled out something from a pocket. I did not see what at first.\""), .direct("What happened after the stabbing?", "\"{D} was shaking and told me to get in the car. I did not know what had happened until we were away from the deck.\""), .direct("What kind of person is {D}?", "\"Kind. {D} does not start fights and has never been violent with me. I was shocked by what I saw.\""), .cross("You did not see {V} swing the jack, did you?", "\"I saw it lifted. I did not see it swing, and I cannot say it hit {D}.\""), .cross("You did not know {D} had a knife, did you?", "\"No. I did not know until I saw it. I never saw {D} carry one before that night.\""), .cross("{D} drove away instead of calling for help, didn't {D.he}?", "\"Yes. We drove off. I was frightened, and I should have said something.\""), .cross("You love {D}, don't you?", "\"Yes. I do, and that makes this hard, but I am describing only what was in front of me.\""), .cross("You are not sure what {V} intended with the jack, are you?", "\"No. I only know what it looked like. I was scared for {D}, and I cannot say what {V} meant.\"")],
        theory: ("{D} stabbed {V} over a bumper.", "A defense against a tire jack."),
        allocution: "\"I never wanted anyone dead.\"",
        truths: ("{DL} texted '{V} is going to pay for the bumper' an hour before.", "A second garage camera shows {V} lifting the tire jack toward {DL}."),
        defendant: [.direct("Did you stab {V}?", "\"Yes. I did. I stabbed {V} twice in the parking deck, and I have not slept well since.\""), .direct("Why did you stab {V}?", "\"{V} came at me with a tire jack. I was scared and pulled out a knife and swung before I could weigh anything.\""), .direct("What was the argument about?", "\"A damaged bumper. {V} said I hit the car, and I said I did not. It got louder and louder.\""), .direct("What did your text mean when you wrote that {V} was going to pay for the bumper?", "\"I was angry and venting to a friend. I meant {V} would have to pay for the damage, not that I would hurt {V}.\""), .direct("Why did you drive away after the stabbing?", "\"I panicked. I was shaking, and I did not know what to do. I should have called for help, and I did not.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not want anyone to be hurt, and I think about what I did every day.\""), .cross("You thrust a knife twice at {V}'s side and chest, didn't you?", "\"Yes. I did. I did not mean to hurt {V} that badly, but I know I did.\""), .cross("You carried a knife in your car, didn't you?", "\"Yes. It is a folding knife I keep for work. It was within reach, and I used it.\""), .cross("You texted that {V} was going to pay an hour before, didn't you?", "\"Yes. I was upset. I did not plan anything, and I regret the text.\""), .cross("You drove away and did not call for help, did you?", "\"No. I did not call. I should have, and I know I made it worse.\""), .cross("You could have walked away, couldn't you?", "\"I could have. I was frightened and I reacted. I wish I had gone back to my car.\"")],
        openings: ("After a concert, {V} and {D} argued over a bumper in a parking deck. {D} thrust a blade twice, and {V} needed emergency surgery for a punctured lung and a cut liver.", "{V} raised a tire jack at {D} in a dark parking deck, and {D} reacted in fear. A second camera shows the jack lifted toward {D}."),
        closings: ("{D} texted that {V} would pay for the bumper, swung a blade twice, and drove away without calling for help. {V} nearly died over a damaged bumper.", "The second camera shows {V} lifting a tire jack toward {D}. {D} acted in a moment of fear and did not go looking for a fight."),
        timeline: [(0, "11:10 p.m.: the bumper dispute."), (0, "11:20 p.m.: the stabbing."), (0, "11:22 p.m.: {DL} drives off."), (0, "11:50 p.m.: {V} reaches the ER.")],
        identified: "A garage camera.",
        aggravating: ["The defendant was armed with a deadly weapon at the time of the crime"],
        mood: .wantsConviction,
        doctrines: ["selfDefense", "imperfectSelfDefense"],
        genders: ["V": .male])

    static let paintCansV1 = SmallCases.make(
        key: "story.paintCans",
        category: .property,
        headlines: ["Shopper Walked Out With Stack of Primer Buckets in Shopping Cart", "Self-Checkout Camera Shows Scan Skipped"],
        law: "larcenyMerchant",
        threshold: 6,
        spec: "Stole $438 in primer and stain from a retail merchant, by passing the point of sale without paying, on {DATE}.",
        ages: 19...55,
        victim: false,
        summary: "A loss-prevention officer at a home store watched {D} load six primer buckets and stain cans, each $73, onto the bottom rack of a cart on {DATE} and scan only the top items at self-checkout. {D} was stopped at the door. {DL} says {D.he} thought the lower rack items were scanned by the overhead sensor.",
        state: [E(.video, 3, "Checkout Camera", "{D} scans one item and rolls the rest past the screen."), E(.document, 3, "Receipt and Loss Sheet", "A receipt for $73 against six items worth $438.")],
        defense: [E(.statement, 1, "Sensor Mistake", "{DL} says {D.he} believed the sensor scanned the lower rack.")],
        role: "Loss-prevention officer",
        exam: [.direct("What is your job at the home store?", "\"I am a loss-prevention officer. I watch the floor and the self-checkout area, review camera footage, and stop customers who leave without paying.\""), .direct("What did you see {D} do on {DATE}?", "\"{D} loaded six primer buckets and stain cans onto the bottom rack of a cart. At self-checkout {D} scanned only the top item.\""), .direct("What were the items worth?", "\"Each can was $73, so six came to $438. The receipt showed a single $73 charge, so $365 of merchandise was not paid for.\""), .direct("What did the checkout camera show?", "\"{D} scanning one item and rolling the rest past the screen. {D} did not scan the cans on the lower rack or place them on the counter.\""), .direct("Where did {D} go after the scan?", "\"Straight toward the exit with the full cart. I stopped {D} at the door and asked to see the receipt.\""), .direct("What did {D} say when you stopped {D.him}?", "\"That {D} thought the sensor under the screen scanned the lower rack. I explained that no sensor does that at this checkout.\""), .cross("{D} did not run when you stopped {D.him}, did {D.he}?", "\"No. {D} stopped right away and answered questions. {D.he} did not try to leave.\""), .cross("The sensor in the checkout is something customers sometimes trust, isn't it?", "\"Yes. Some stores have overhead scanners. Ours does not scan the lower rack, but customers may be used to others.\""), .cross("The cans were heavy and sat on the bottom rack, weren't they?", "\"Yes. They are heavy. Many shoppers put them on the lower rack, and it is common.\""), .cross("{D} paid for one can without difficulty, didn't {D.he}?", "\"Yes. {D} paid with a card for the one can. {D} did not argue or hesitate at the screen.\""), .cross("You cannot know what {D} believed, can you?", "\"No. I can say what the camera shows. What {D} believed is for the jury.\"")],
        theory: ("{D} scanned one can and walked out with six.", "A shopper who trusted a sensor."),
        allocution: "\"I made a mistake.\"",
        truths: ("{DL} had been stopped for an unscanned cart at a store across town a month before.", "{DL} paid for the one can twice with a card and asked the cashier for help."),
        defendant: [.direct("Did you try to take paint without paying?", "\"No. I tried to scan everything. I thought the lower rack was covered by a sensor, and I paid for what I thought I was buying.\""), .direct("Why did you put the cans on the lower rack?", "\"They were heavy. I did not want to lift them onto the counter, and I thought the sensor under the screen would read them.\""), .direct("Did you look at the screen?", "\"I did not look closely. I scanned the top item and expected the rest to register. I trusted the system.\""), .direct("What did you do when the officer stopped you?", "\"I stopped and showed the receipt. I told the officer what I thought, and I offered to pay for the rest right then.\""), .direct("Why did you use self-checkout?", "\"It was faster. I had a few other errands, and I wanted to get out quickly. I do it often.\""), .direct("What would you say to the store?", "\"That I am sorry for the confusion. I did not mean to steal, and I am willing to pay for every can.\""), .cross("You were stopped at a store across town a month ago for an unscanned cart, weren't you?", "\"Yes. It was a similar misunderstanding. I should have been more careful after that.\""), .cross("You scanned one item and walked out with six, didn't you?", "\"The video shows that. I did not realize the others had not scanned, and I should have checked the receipt.\""), .cross("You never looked at the receipt before you left, did you?", "\"No. I did not check it. I trusted the machine.\""), .cross("You paid for the one can twice with a card, didn't you?", "\"Yes. I paid twice and asked the cashier for help. It was a confusing checkout.\""), .cross("The sensor does not scan the lower rack, does it?", "\"I learned that only after I was stopped.\"")],
        openings: ("A loss-prevention officer watched {D} load six primer and stain cans onto the lower rack of a cart and scan only one at self-checkout. The receipt showed $73 against $438 of merchandise.", "{D} trusted an overhead sensor to scan the lower rack and never noticed the mistake. A confusing checkout is not a theft."),
        closings: ("One scan, six cans, and a walk to the exit. A month earlier {D} had been stopped for an unscanned cart at another store.", "{D} stopped when asked, showed the receipt, and offered to pay for every can on the spot. A shopper who trusts a sensor is not a shoplifter."),
        timeline: [(0, "Noon: the cart is loaded."), (0, "12:15 p.m.: the self-checkout."), (0, "12:20 p.m.: {DL} is stopped at the door.")],
        identified: "A loss-prevention officer's camera.",
        mood: .indifferent,
        genders: ["D": .male])

    static let repeatBarAssaultV1 = SmallCases.make(
