    static let campusLaptopV1 = SmallCases.make(
        key: "story.campusLaptop",
        category: .property,
        headlines: ["Dorm Study Lounge Laptop Pawned Across Town", "Serial Number Check Links Lost Computer to Pawn Customer"],
        law: "possStolen",
        spec: "Possessed a laptop computer valued at $840 belonging to {V}, knowing and having reasonable grounds to believe it stolen, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "{V} left a laptop on a study lounge couch while getting food on {DATE} and returned to an empty couch. Four days later {D} sold the laptop to a computer repair shop. The shop's serial check matched {V}'s report. {DL} says {D.he} bought it from a seller in a marketplace app for $150 and had the receipt chat.",
        state: [E(.document, 3, "Repair Shop Bill of Sale", "{D}'s ID on a sale of a laptop whose serial matches {V}'s receipt."), E(.video, 2, "Lounge Camera", "A person in a hoodie lifts a laptop from a couch.")],
        defense: [E(.digital, 1, "Marketplace Chat", "A chat in which a seller offers a laptop for $150.")],
        role: "Repair shop owner",
        exam: [.direct("What is your business?", "\"I own a computer repair shop. We fix laptops and phones, and we buy and resell used equipment when it checks out. I check serial numbers on every purchase.\""), .direct("Who sold you the laptop four days after it went missing?", "\"{D}. {D} gave a license, and I filled out a bill of sale with the serial number, the price and the date in the shop's book.\""), .direct("What did the serial check show?", "\"A police flag. The serial matched a theft report that {V} had filed, and the receipt {V} gave us listed the same number.\""), .direct("How did {D} behave at the counter?", "\"Friendly. {D} haggled a little over the price and said the laptop came from a marketplace app. {D} showed me a chat on a phone.\""), .direct("What did you do after the check came back?", "\"I called the sheriff's office and held the laptop. A deputy came and collected it. I handed over the bill of sale and the copy of {D}'s ID.\""), .direct("What price did {D} ask?", "\"About $250 at first, and we settled lower. I do not remember exactly, but it was well below what the laptop would sell for.\""), .cross("{D} used a real ID, didn't {D.he}?", "\"Yes. {D} gave a state license, and the address was real. {D} did not try to hide who {D.he} was.\""), .cross("{D} showed you a chat with the seller, didn't {D.he}?", "\"Yes. {D} held up a phone with a chat about a laptop and a $150 price. I did not read it closely.\""), .cross("People sell used laptops to your shop every day, don't they?", "\"Yes. Most are legitimate. We check serials because some are not.\""), .cross("{D} did not rush or try to leave, did {D.he}?", "\"No. {D} stayed at the counter and waited. {D} seemed to expect a normal sale.\""), .cross("You do not know where {D} got the laptop, do you?", "\"No. I only know what {D} told me and what the chat showed. I did not see how {D} obtained it.\"")],
        theory: ("{D} sold a laptop that had just been stolen.", "A buyer from an app who trusted a seller."),
        allocution: "\"I should not have bought it at that price.\"",
        truths: ("The marketplace account was created two hours before the chat from {DL}'s own phone.", "The chat shows the seller sending a photo of a student ID with a different name and {DL} asking if it was stolen."),
        defendant: [.direct("Where did you get the laptop?", "\"On a marketplace app. A seller offered it for $150, and I met the seller to pick it up. I paid cash and went home.\""), .direct("Why did you buy it?", "\"I thought it was a good deal. I planned to fix it up and sell it for a profit. I buy and sell used electronics now and then.\""), .direct("Did you ask the seller whether the laptop was stolen?", "\"Yes, in the chat. The seller said no and sent a photo of a student ID. I took the answer at face value.\""), .direct("Why did you take it to the repair shop?", "\"To sell it. I did not need it. I used my own ID and told the owner where I got it.\""), .direct("How did you feel when the owner called the sheriff?", "\"Surprised and scared. I explained everything and showed the chat. I wanted the laptop to go back to the owner.\""), .direct("What would you say to {V}?", "\"That I am sorry for the trouble. I did not know the laptop was stolen, and I should have asked more questions.\""), .cross("You knew $150 was a bargain, didn't you?", "\"Yes. I knew it was a deal. I thought I was just lucky, and I should have wondered why.\""), .cross("The marketplace account was created two hours before the chat, wasn't it?", "\"That is what I learned later. I did not check how old the account was.\""), .cross("The seller's student ID had a different name on it, didn't it?", "\"Yes. I noticed the name was different. I did not ask more about it, and I should have.\""), .cross("You asked in the chat whether it was stolen, didn't you?", "\"I did. I asked, and the seller said no. I should have walked away when the answers did not feel right.\""), .cross("You sold it four days after the theft, didn't you?", "\"Yes. I know how it looks. I did not know it had just been stolen.\"")],
        openings: ("{V} left a laptop on a lounge couch and returned to an empty couch. Four days later, {D} sold the laptop to a repair shop, and its serial number matched {V}'s report.", "{D} bought a laptop from a marketplace seller who said it was not stolen. {D} sold it under a real ID and kept the chat."),
        closings: ("A serial number that matches, a sale four days after the theft, and a bargain price. {D} asked if it was stolen and went ahead anyway.", "{D} used a real ID, kept the chat, and asked the seller directly. A buyer who is lied to is not the thief."),
        timeline: [(0, "Afternoon: the laptop is taken."), (3, "{DL} buys it online."), (4, "{DL} sells it to the repair shop."), (5, "The shop's serial check flags it.")],
        identified: "The repair shop's serial check.",
        genders: ["D": .male, "V": .female])

    static let barGlassInjuryV1 = SmallCases.make(
        key: "story.barGlassInjury",
        category: .violent,
        headlines: ["Pint Glass Smashed Into Face at Pool Hall", "Bar Surveillance Shows Swing After Cue Dispute"],
        law: "aisi",
        threshold: 7,
        spec: "Assaulted {V} inflicting serious injury, on {DATE}.",
        ages: 21...45,
        victim: true,
        summary: "At a pool hall on {DATE}, {D} and {V} argued over a cue stick. {D} swung a pint glass and {V} needed surgery for a broken jaw. A server watched {D} swing. {DL} says {V} grabbed {D.him} by the shirt first.",
        state: [E(.statement, 3, "Server", "{D} swung the pint glass at {V}'s face."), E(.forensic, 2, "Medical Records", "A broken jaw needing surgery and wires."), E(.document, 2, "Manager Report", "The pool hall manager lists {D} as holding the glass.")],
        defense: [E(.statement, 1, "Grabbed Shirt", "{DL} says {V} grabbed {D.him} by the shirt.")],
        role: "Server",
        exam: [.direct("What is your job at the pool hall?", "\"I am a server. I bring drinks to the tables, clear glasses, and keep an eye on the floor. I was working the night of {DATE}.\""), .direct("What started the argument between {D} and {V}?", "\"A cue stick. They disagreed over whose it was after a game, and the voices got louder. I came over to see if I could help.\""), .direct("What did you see {D} do?", "\"{D} swung a pint glass at {V}'s face. It was a full swing, and the glass broke on contact. {V} went down.\""), .direct("What happened to {V}?", "\"{V} fell back and held {V}'s jaw. There was blood and {V} could not speak clearly. I called 911 and brought towels.\""), .direct("What did {V} suffer?", "\"A broken jaw. {V} needed surgery and wires. I learned that later from the manager.\""), .direct("What did the manager do?", "\"The manager separated the two and held {D} until deputies arrived. The manager wrote a report that lists {D} as holding the glass.\""), .cross("You saw a hand on {D}'s shirt before the swing, didn't you?", "\"Yes. I saw a hand on the shirt. I cannot say how hard it was or how long it lasted.\""), .cross("It was just before the swing, wasn't it?", "\"Very close to it. A moment before. I could not tell who grabbed first.\""), .cross("The collar on {D}'s shirt was torn, wasn't it?", "\"I saw that later. It could have happened in the grab or at another time. I did not see it tear.\""), .cross("You did not hear the first words of the argument, did you?", "\"No. I walked up as it was getting loud. I only saw the end of it.\""), .cross("The glass was in {D}'s hand before the grab, wasn't it?", "\"I believe so. {D} was drinking from it. I cannot say when {D} lifted it.\"")],
        defenseRole: "Defendant's coworker",
        defenseExam: [.direct("How do you know {D}?", "\"I am {D}'s coworker. We have worked together for about three years, and we are on the same shift most weeks.\""), .direct("Were you at the pool hall that night?", "\"Yes. I was playing a game with friends nearby. I had a good view of the argument at the next table.\""), .direct("What did you see {V} do?", "\"{V} grabbed {D} by the shirt hard. {V} pulled {D} forward, and the collar ripped. I heard the tear.\""), .direct("How did {D} react?", "\"{D} looked frightened. {D} tried to pull away and then swung the glass. It all happened in two seconds.\""), .direct("What kind of person is {D}?", "\"Even-tempered. I have never seen {D} in a fight. {D} is the one who calms others down at work.\""), .direct("What did you do after the swing?", "\"I turned away. I could not look. I heard the glass break and then people shouting.\""), .cross("You did not see who grabbed first, did you?", "\"I saw {V} grab {D}. I did not see what happened before that, and I cannot say who started it.\""), .cross("You are {D}'s coworker, aren't you?", "\"Yes. I like {D}. I am telling you what I saw, and I do not want to hide anything.\""), .cross("You turned away at the swing, didn't you?", "\"Yes. I did. I did not see the glass hit {V}.\""), .cross("You cannot say how long {V} held the shirt, can you?", "\"No. It was a second or two. I do not have a clear count.\""), .cross("A glass in someone's hand is dangerous, isn't it?", "\"Yes. It is. I wish {D} had put it down.\"")],
        theory: ("{D} hit {V} with a pint glass.", "A swing after a shirt grab."),
        allocution: "\"I am sorry.\"",
        truths: ("A patron says {DL} threw the first punch before any grab.", "{DL}'s shirt had a torn collar from {V}'s grip."),
        defendant: [.direct("Did you swing the pint glass at {V}?", "\"Yes. I did. I swung it, and I did not mean to hurt {V} that badly. I have been sick over it.\""), .direct("Why did you swing?", "\"{V} grabbed me by the shirt hard. I was scared. I swung the glass to get free, and I did not think about what could happen.\""), .direct("What was the argument about?", "\"A cue stick. {V} thought I had picked up the wrong one. I told {V} it was mine, and {V} got in my face.\""), .direct("What did you do after the swing?", "\"I stood there stunned. I dropped what was left of the glass. I told the manager I was sorry and waited.\""), .direct("Were you hurt?", "\"My shirt was torn at the collar, and my neck was red. I was not seriously hurt.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to break {V}'s jaw. I will do whatever I can to help.\""), .cross("A patron says you threw the first punch before any grab, doesn't the patron?", "\"I have heard that. My memory is different: I felt the grab first.\""), .cross("You swung a glass at someone's face, didn't you?", "\"Yes. I did. It was a terrible choice, and I know that.\""), .cross("You could have walked away, couldn't you?", "\"I tried to turn. I was held, and I was scared. I know I could have used other options.\""), .cross("The glass broke on {V}'s face, didn't it?", "\"Yes. It did. I saw the blood, and I will never forget it.\""), .cross("You were holding a pint glass during an argument, weren't you?", "\"Yes. I had been drinking from it. I should have put it down.\"")],
        openings: ("At a pool hall, {D} and {V} argued over a cue stick. {D} swung a pint glass at {V}'s face, and {V} needed surgery and wires for a broken jaw. A server watched it happen.", "{V} grabbed {D} by the shirt hard enough to tear the collar. {D} swung in a moment of fear to get free."),
        closings: ("A pint glass in {D}'s hand, a swing at {V}'s face, and a broken jaw. A patron says {D} threw the first punch before any grab.", "A torn collar, a hand on a shirt, and a coworker who saw {V} grab first. {D} reacted in two seconds and is deeply sorry."),
        timeline: [(0, "10 p.m.: the cue argument."), (0, "10:20 p.m.: the grab."), (0, "10:21 p.m.: the swing."), (0, "10:50 p.m.: deputies arrive.")],
        identified: "A server.",
        aggravating: ["The offense involved a victim who suffered serious injury"],
        mood: .divided,
        doctrines: ["selfDefense"],
        genders: ["V": .male])

    static let scrapGuttersV1 = SmallCases.make(
        key: "story.scrapGutters",
        category: .property,
        headlines: ["Copper Downspouts and Flashing Stripped From Empty Rental", "Recycler's Photo Log Leads to Seller"],
        law: "misdLarceny",
        spec: "Stole copper downspouts and roof flashing valued at $700 belonging to {V}, from a vacant house, on {DATE}.",
        ages: 20...58,
        victim: true,
        summary: "{V} owns a vacant rental house that was awaiting new tenants. During a week in {DATE}, copper downspouts and roof flashing disappeared. A recycler's photo log shows {D} dropping off 45 pounds of copper that Thursday. {DL} says {D.he} pulled it from a demolition job that a contractor told {D.him} to haul away.",
        state: [E(.document, 3, "Recycler's Photo Log", "{D}'s ID, truck and a pile of copper downspouts and flashing."), E(.physical, 2, "Scene Photos", "Bare brackets and cut flashing on the house.")],
        defense: [E(.statement, 1, "Demolition Haul", "{DL} says a contractor told {D.him} to haul copper from a teardown.")],
        role: "Recycling yard clerk",
        exam: [.direct("What is your job at the recycling yard?", "\"I am a clerk at the scale. I weigh materials, check IDs, pay out cash, and take a photo of each load that comes in.\""), .direct("What did {D} bring to the yard that Thursday?", "\"About 45 pounds of copper, mostly downspouts and flashing. It was in the bed of a truck. I weighed it and wrote a ticket.\""), .direct("How was {D} paid?", "\"Cash for the weight. I handed over the money and had {D} sign. I photographed the truck, the ID and the pile.\""), .direct("What did you notice about the copper itself?", "\"The pieces looked fresh-cut. The edges were bright and sharp, and some of the pieces still had nails and brackets attached.\""), .direct("What did {D} say about where it came from?", "\"A demolition job. {D} said a contractor told {D.him} to haul it away. {D} gave a first name for the contractor and nothing else.\""), .direct("Why did the yard keep a photo log?", "\"It is required by the county. It helps us identify people if copper is later reported stolen, as it was here.\""), .cross("{D} used a real ID, didn't {D.he}?", "\"Yes. {D} gave a license, and the truck was registered to {D}. {D} did not hide anything.\""), .cross("{D} gave you a contractor's first name, didn't {D.he}?", "\"Yes. It was a first name. I did not write it down, and I cannot recall it now.\""), .cross("Many people bring cut copper to the yard from demolition jobs, don't they?", "\"Yes. It is very common. Most of it is legitimate, though we have to be careful.\""), .cross("Nothing about {D} seemed nervous, did it?", "\"Not that I noticed. {D} was relaxed and talked about the weather. It seemed like an ordinary load.\""), .cross("You do not know where the copper came from, do you?", "\"No. I only know what was told to me and what the photo log shows. I was not at the house.\"")],
        theory: ("{D} stripped copper off a vacant house and sold it.", "A hauler paid to clear a teardown."),
        allocution: "\"I should have asked for paperwork.\"",
        truths: ("{DL}'s truck appears on the house's neighbor's camera on Wednesday night.", "The contractor later confirmed paying {DL} to haul and said {DL} took the wrong house."),
        defendant: [.direct("Where did you get the copper?", "\"From a teardown job. A contractor told me to haul away the old copper from a house and gave me the address.\""), .direct("Whose house did you think you were at?", "\"The contractor's job. I went to the address I was given. I did not know it was a different house.\""), .direct("Did you cut the copper yourself?", "\"Some of it. The downspouts were still attached, and I used a hacksaw to take them off the brackets.\""), .direct("Did you get any paper from the contractor?", "\"No. It was a verbal job. I was told to take it and keep what I could get for it.\""), .direct("Why did you sell the copper at the recycling yard?", "\"It was payment for the haul. I took it to the yard the next day and used my own ID.\""), .direct("How did you feel when you learned the house was not part of the job?", "\"Sick. I called the contractor, who said I went to the wrong address. I wanted to pay for what I had taken.\""), .cross("The house was vacant and not a teardown, wasn't it?", "\"I know that now. I should have checked that the house matched the job. I did not.\""), .cross("Your truck was on a neighbor's camera Wednesday night, wasn't it?", "\"Yes. I was there that night. I was doing the job I was told to do.\""), .cross("You cut the copper yourself, didn't you?", "\"Some. The pieces I cut were cut by me. I thought I was authorized.\""), .cross("You did not get anything in writing, did you?", "\"No. I should have. It was a handshake job.\""), .cross("You took 45 pounds of copper from a house that was not part of the job, didn't you?", "\"Yes. I did. I went to the wrong house, and I did not stop to check.\"")],
        openings: ("{V} owns a vacant rental house that lost its copper downspouts and roof flashing during one week. A recycler's photo log shows {D} dropping off 45 pounds of copper that Thursday.", "{D} was paid by a contractor to haul copper from a teardown job and went to the wrong house by mistake. The contractor later confirmed the haul and the pay."),
        closings: ("The recycler's photo log shows {D}'s truck and a pile of fresh-cut copper from {V}'s house. {D}'s truck was on a neighbor's camera there Wednesday night.", "A contractor later confirmed paying {D} to haul copper and said {D} went to the wrong house by mistake. A wrong address is a mistake and not a plan to steal."),
        timeline: [(-2, "{V} last checks the house."), (0, "Wednesday night: the copper is stripped."), (1, "Thursday: {DL} sells it."), (6, "{V} finds the bare roof edge.")],
        identified: "A recycler's photo log.",
        genders: ["D": .male])

    static let debtKidnappingV1 = SmallCases.make(
        key: "story.debtKidnapping",
        category: .violent,
        headlines: ["Borrower Held in Basement Over Unpaid Loan, Deputies Say", "Escape Through Cellar Window Ends Two-Day Ordeal"],
        law: "kidnapping1",
        threshold: 8,
        spec: "Unlawfully confined and restrained {V} for the purpose of terrorizing {V.him} and to collect a debt, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "{V} owed {D} $3,500. On {DATE}, {D} and a helper drove {V} to a house, tied {V.his} wrists with rope and locked {V.him} in a basement for two days. {V} broke a window and ran to a gas station. {DL} says {V} agreed to stay while friends gathered the money.",
        state: [E(.statement, 3, "Victim", "Tied with rope and locked in a basement for two days."), E(.physical, 3, "Rope and Padlock", "A cut rope and a padlock on the outside of the basement door.", .search), E(.forensic, 2, "Medical Records", "Rope burns on both wrists.")],
        defense: [E(.statement, 1, "Agreed to Stay", "{DL} says {V} agreed to stay.")],
        role: "Sheriff's detective",
        exam: [.direct("What did you find when you went to the house?", "\"A length of rope and a padlock outside a basement door. The window in the basement was broken, and glass lay on the grass.\""), .direct("How did {V} get out?", "\"By breaking a basement window and climbing out. {V} ran to a gas station and called for help. The clerk phoned 911.\""), .direct("What did {V} look like when you saw {V}?", "\"Frightened and exhausted, with rope burns on both wrists. {V} had a few cuts from the glass and said {V} had been locked in for two days.\""), .direct("What did {V} tell you about how {V} got there?", "\"{D} and a helper drove {V} to the house, tied {V.his} wrists with rope, and locked {V.him} in the basement. {V} owed {D} $3,500.\""), .direct("What did you find on {D}'s keyring?", "\"The padlock keys. They fit the lock we found at the basement door, and {D} had them on {D.his} keyring when we arrested {D.him}.\""), .direct("What did the medical records show?", "\"Rope burns on both wrists. {V} was treated for the burns and the cuts and was released the same day.\""), .cross("{V} did text a friend that {V} would stay, didn't {V}?", "\"Yes. A text to a friend said {V} would stay in the basement until it was sorted. I read it, and I have thought about the circumstances.\""), .cross("{V} did say yes at some point, didn't {V}?", "\"Under pressure, yes. {V} told me {V} agreed because {V} was afraid and did not feel there was another choice.\""), .cross("The rope was loosely tied, wasn't it?", "\"{D} says so. The burns on {V}'s wrists suggest it was tight enough to hurt.\""), .cross("{V} owed {D} money, didn't {V}?", "\"Yes. $3,500. That is not disputed. The debt does not allow locking someone in a basement.\""), .cross("You did not see {D} lock the door, did you?", "\"No. I rely on {V}'s statement, the keys, and the physical evidence.\"")],
        defenseRole: "Defendant's helper",
        defenseExam: [.direct("How are you connected to {D}?", "\"I helped {D}. I was asked to drive along and watch the house, and I agreed. I did not think it would turn into what it did.\""), .direct("Why was {V} in the basement?", "\"{V} said it was fine. {V} said {V} would stay until friends brought the money, and nobody argued.\""), .direct("Was the door locked?", "\"At night, yes. {D} locked it. I was told it was so {V} would not leave in the dark.\""), .direct("How did {V} seem?", "\"Quiet. {V} watched TV and ate what we brought. I did not see {V} resist or ask to leave.\""), .direct("Did you tie {V}'s wrists?", "\"I saw rope on {V}'s wrists. I did not tie it. I was told it was loose.\""), .direct("What did you do when you learned {V} had escaped?", "\"I was shocked. I called {D}, and we went to find out what happened. I realized we had gone too far.\""), .cross("You saw {V} tied and locked in a basement, didn't you?", "\"Yes. I did. I did not stop it, and I should have.\""), .cross("{V} never said yes freely, did {V}?", "\"I do not know. {V} did not say no loudly, but I now see how that could happen.\""), .cross("You did not call the sheriff's office, did you?", "\"No. I did not. I was scared of getting in trouble.\""), .cross("You helped drive {V} to the house, didn't you?", "\"Yes. I did. I regret that every day.\""), .cross("You were paid for your help, weren't you?", "\"I was promised a small share of the money. I never got it.\"")],
        theory: ("{D} locked up a debtor to collect.", "A debtor who agreed to stay."),
        allocution: "\"I lost my temper over the money.\"",
        truths: ("The padlock keys were on {DL}'s keyring.", "{V}'s texts to a friend said 'I'll stay in {DL}'s basement until it's sorted.'"),
        defendant: [.direct("Did you lock {V} in the basement?", "\"At night, yes. I did. I locked the door because I was afraid {V} would run, and I know now how wrong that was.\""), .direct("Why did you take {V} to the house?", "\"{V} owed me $3,500 and said friends would gather it. I wanted to make sure {V} stayed until I was paid.\""), .direct("Did you tie {V}'s wrists?", "\"Loosely. I wanted {V} to stay put. I did not mean to hurt {V}, and I did not think about the rope burns.\""), .direct("Why did you use a padlock?", "\"To keep {V} there. I wanted {V} to wait until the money was gathered. I know it was serious.\""), .direct("What did {V} say about staying?", "\"{V} said it was fine and that friends would come with money. I took that as agreement.\""), .direct("What would you say to {V}?", "\"That I am sorry. I should not have locked you up, and I should have found another way to deal with the debt.\""), .cross("The padlock keys were on your keyring, weren't they?", "\"Yes. I kept them with me. I know that shows I controlled the door.\""), .cross("{V} was locked in for two days, wasn't {V}?", "\"Yes. I was away part of the time. A helper watched the house.\""), .cross("{V} broke a window to get out, didn't {V}?", "\"Yes. I know that. It tells me {V} wanted to leave, and I should have let {V} go.\""), .cross("You tied {V}'s wrists, didn't you?", "\"Yes. I did. I told myself it was loose, but I know it was a bad choice.\""), .cross("You could have called the sheriff's office about the debt, couldn't you?", "\"Yes. I could have, and I should have. I did not know how to collect, and I took the wrong path.\"")],
        openings: ("{V} owed {D} $3,500. {D} and a helper drove {V} to a house, tied {V.his} wrists with rope, and locked {V.him} in a basement for two days. {V} broke a window and ran to a gas station.", "{V} agreed to stay while friends gathered the money. {D} says that agreement was real, and a text from {V} says so."),
