        defense: [E(.statement, 1, "Permitted Wall", "{DL} says a permitted mural was planned for the next week.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did the railroad report on {DATE}?", "\"A 50-foot concrete wall under a bridge had been covered overnight with a large painted tag. The railroad put the cleanup cost at $2,100.\""), .direct("Where did you find {D}?", "\"Sitting in a parked car near the bridge at about 3 a.m. The car was parked on a gravel shoulder, and I saw a figure moving around it.\""), .direct("What did you find in {D}'s car?", "\"Nine spray paint cans in the back seat. Several were open, and some had fresh paint on the nozzles.\""), .direct("What did you notice about {D}'s clothing?", "\"Paint stains on both sleeves. They were fresh and matched the color of the tag on the wall.\""), .direct("What did the railroad camera show?", "\"A figure with a backpack near the wall at 2:20 a.m. The face was not visible, and the camera was dark and grainy.\""), .direct("What did {D} tell you?", "\"That {D} was holding the cans for a friend who was painting a permitted wall. {D} said {D.he} did not paint the bridge.\""), .cross("The figure on camera has no visible face, does it?", "\"No. I cannot say from the camera that the person was {D}.\""), .cross("{D} was cooperative when you found {D.him}, wasn't {D.he}?", "\"Yes. {D} answered questions and let me look in the car. {D} did not run.\""), .cross("Many people carry spray paint for permitted work, don't they?", "\"Yes. Muralists carry many cans. I have no reason to doubt that some are used legally.\""), .cross("A permit for a mural was planned for the next week, wasn't it?", "\"That is what {D} says. I did not find a permit for the bridge wall, and the permitted wall was elsewhere.\""), .cross("You did not see anyone paint the wall, did you?", "\"No. I found {D} after the tag was done. I did not see who painted it.\"")],
        theory: ("{D} tagged a railroad wall and had the paint on {D.his} clothes.", "A courier of cans for a friend's permitted project."),
        allocution: "\"I made a stupid choice.\"",
        truths: ("{DL}'s phone held a photo of the wall with 'my name' as a caption.", "The friend with the permit confirmed {DL} only carried cans and left before painting."),
        defendant: [.direct("Did you paint the tag on the bridge?", "\"No. I did not. I was holding paint cans for a friend, and I never touched that wall.\""), .direct("Why did you have nine paint cans?", "\"I was carrying them for a friend who was working on a permitted mural the following week. I was helping with the supplies.\""), .direct("Why were you parked near the bridge at 3 a.m.?", "\"My friend works nights, and we planned to meet there. I waited, and then a deputy came by.\""), .direct("How did the paint get on your sleeves?", "\"I carried the cans and some had drips on the outside. I wiped them on my sleeves. I did not paint anything.\""), .direct("What did you do when the deputy came?", "\"I told the deputy everything. I showed the cans and said who they were for.\""), .direct("What would you say to the railroad?", "\"That I am sorry for the damage. I did not do it, but I understand why I was suspected.\""), .cross("You had a photo on your phone of the wall with a caption, didn't you?", "\"Yes. It said 'my name.' I was joking with friends. I did not paint it.\""), .cross("You had paint on your sleeves, didn't you?", "\"Yes. From carrying cans. I know how it looks.\""), .cross("You were near the wall at 3 a.m., weren't you?", "\"Yes. I was waiting for my friend. I know that is a bad coincidence.\""), .cross("Nine cans is a lot to hold for a friend, isn't it?", "\"Yes. It was a big mural. I did not think about how it would seem.\""), .cross("You cannot show the permit for the bridge wall, can you?", "\"No. The permit was for a different wall. I never claimed it was for the bridge.\"")],
        openings: ("A 50-foot concrete wall of a railroad bridge was covered with a large painted tag. A deputy found {D} in a parked car near the bridge at 3 a.m. with nine paint cans and paint stains on {D.his} sleeves.", "{D} was holding cans for a friend with a permit for a different wall. {D} did not paint the bridge and told the deputy so at once."),
        closings: ("Nine cans, fresh paint on {D}'s sleeves, a photo of the wall captioned with a name, and a car near the bridge at 3 a.m. The pieces fit.", "The friend with the permit confirmed {D} only carried cans and left before any painting. Stains from carrying cans are not proof of a tag."),
        timeline: [(0, "2:20 a.m.: a figure at the wall on camera."), (0, "2:50 a.m.: the tag is finished."), (0, "3 a.m.: {DL} is found in a nearby car.")],
        identified: "A deputy's patrol and a railroad camera.",
        genders: ["D": .male])

